  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('serpent-beast', 'mystic-spider', 'monster-toad', 'serpent-man', 'pseudo-demon-guard', 'low-caste-pseudo-demon', 'tomb-worm', 'minotaur-old-ones', 'zombie-of-artimus');
