INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('serpent-beast', 'Serpent Beast', 'monster', 'palladium-fantasy', 0, 'Animal, extremely hostile', NULL, '110', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":2,"strike":1}', 'First-edition figures, as printed. +2 to save vs. magic. Poison save: 10 or higher, rolled for each bite. Poisoned victims are -3 to strike, parry and dodge for the next 16 hours.', NULL, 'Its bite carries a venom that adds damage and brings on a sudden high fever, leaving the victim weakened in combat for most of a day.', NULL, NULL, '24 ft long from head to tail', NULL, NULL, 'A foul natural tunnel about 9 ft wide and 8 ft tall off the cave at area 17-18 of the Hidden Temple', NULL, NULL, NULL, 'A starving predator from a past age with a snake''s body, four short legs and a human face, which kills all it can and hauls the bodies to its tunnel to eat. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.145-146'),
('mystic-spider', 'Mystic Spider', 'monster', 'palladium-fantasy', 0, 'None', NULL, '30', NULL, NULL, NULL, NULL, NULL, 8, NULL, '{"attacks":1,"strike":2,"dodge":3}', 'First-edition figures, as printed. A.R. 8 is natural. Speed 20.', 'Climb (even smooth surfaces) 90%.', 'Senses magic within 120 ft and has 120 ft nightvision. Its light beam removes one spell from a caster''s daily total per hit, painlessly; the loss is not permanent.', NULL, NULL, 'Body 3 ft across; about 5 ft tall on its legs', NULL, NULL, 'The Secret Complex of the Old Ones, sections 3, 6 and 24 especially', NULL, NULL, NULL, 'A featureless spider-like thing that feeds on magic and trails spell casters, wards and circles to drain them. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.157'),
('monster-toad', 'Monster Toad', 'monster', 'palladium-fantasy', 0, 'None/animal/hostile', NULL, '2D4x10', NULL, NULL, NULL, NULL, 'Hit Points printed as 20-80.', 6, NULL, '{"attacks":2,"strike":1}', 'First-edition figures, as printed. A.R. 6 is natural. Speed 9. A Range of 10ft is printed with no statement of what it measures.', 'Track by smell 60%.', 'Nightvision 60 ft and sees the invisible to 30 ft. Big teeth and thin legs; it manages only short hops and hunts any humanoid without wings.', NULL, NULL, '6 ft tall, 9 ft long', NULL, NULL, 'The Secret Complex of the Old Ones; three are kept chained in the arena (area 19) by the serpent men', 'Kept by the serpent men for sport, hunting and as watch animals', NULL, NULL, 'A fierce toad-like predator that is little like a true toad, used by the serpent men of the Old Ones'' complex much as guard dogs. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.157'),
('serpent-man', 'Serpent Man', 'humanoid', 'palladium-fantasy', 0, 'Any, but usually selfish', NULL, '6D6+6', NULL, NULL, NULL, NULL, 'Hit Points printed as 6-36+6.', 12, NULL, '{"attacks":3,"strike":2,"parry":4,"dodge":4}', 'First-edition figures, as printed. A.R. 12 is natural. +3 to save vs. magic. Attacks are printed as 2 hand to hand plus one with the tail. Speed running 10. Those trying to prowl up on them are -10% to prowl and -3 on initiative.', 'Prowl 60%.', 'Flies at 25 mph, has 120 ft nightvision and very sharp hearing, and is fast and nimble. The tail lashes like a whip or wraps around a target to hold or choke it.', NULL, NULL, '6 to 7 ft tall standing; 16 ft from tail tip to nose; wing-spread 15 ft', NULL, NULL, 'The Secret Complex of the Old Ones, reached from their own world through the dimensional rift circle in area 6', NULL, NULL, NULL, 'Tall winged serpent folk, the ruling species of another world, whose tribe has settled in the Old Ones'' complex. Not evil and gentle with their own kind, they hunt mammals as food and speak only in simple grunts, clicks and whines. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.158'),
('pseudo-demon-guard', 'Pseudo-Demon Guard', 'humanoid', 'palladium-fantasy', 0, 'Selfish or Evil (any)', '{"PS":"20","Spd":"17"}', '3D6+10', NULL, NULL, NULL, NULL, 'Hit Points printed as 3-18 +10.', 12, NULL, '{"attacks":2,"damage":6}', 'First-edition figures, as printed. Those with a tail have an extra attack. +2 on all saves, 1/2 damage from fire or cold. Spells: none. Weapon proficiencies: Short sword +2 to strike, +2 parry/dodge, +1 throw; Large sword +2 to strike, +3 parry/dodge; Spear +2 to strike, +3 parry/dodge, +1 throw; Knives +2 to strike, +2 parry/dodge, +1 throw. Weapons: one dagger, plus a roll of a six-sided die for 1 short sword, 2 cutlass, 3 bastard sword, 4 long sword, 5 short spear, 6 long spear. Possessions: set of clothes, boots, large sack, bottle of low quality wine, 2-12 silver pieces.', NULL, 'Oversized claws or fangs, sharp teeth and claws, plus two rolls on the Contagion extra abilities table.', NULL, NULL, '1-6 feet over the standard height for their race', NULL, NULL, 'The canals beneath the Place of Magic', NULL, NULL, 'Printed as a 3rd level Mercenary.', 'The standard fighter of the pseudo-demon tribe: a sullen, scaly or leathery victim of the Contagion who fights to break the tedium and torments captives for fun. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.174'),
('low-caste-pseudo-demon', 'Low Caste Pseudo-Demon', 'humanoid', 'palladium-fantasy', 0, 'Varies, but often anarchist', '{"PS":"18"}', '3D6', NULL, NULL, NULL, NULL, 'Hit Points printed as 3-18.', 10, NULL, '{"attacks":1,"damage":3}', 'First-edition figures, as printed. +2 on all saves. Other attributes average. Spells: none. Weapon proficiencies: Knives +1 to strike, +1 parry/dodge, +1 throw. Weapons: dagger (no damage printed). Possessions: ragged clothing, belt, large empty sack, low quality dagger and/or spear.', NULL, 'Sharp teeth, claws and horns, 60 ft nightvision, and two rolls on the Contagion extra abilities table.', NULL, NULL, 'Grossly tall or fat versions of their races', NULL, NULL, 'The canals beneath the Place of Magic', NULL, NULL, 'No special skills; a former serf or slave.', 'The downtrodden bottom rank of the pseudo-demon tribe: hairless, lumpy green or grey victims of the Contagion, fearful of nearly everything and obedient to whoever bullies them. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.174'),
('tomb-worm', 'Tomb Worm', 'monster', 'palladium-fantasy', 0, NULL, NULL, '12', NULL, NULL, NULL, NULL, NULL, 2, NULL, '{"attacks":1}', 'First-edition figures, as printed. Spd. 8. If not killed, a worm reaches a vital organ in 12 melees.', NULL, 'Finds flesh by smell or some other sense and crawls toward it to feed, tunnelling into the body.', NULL, NULL, '8 inches long', NULL, NULL, 'A heap of rotted wood at the T-Entry storage room of the tunnels beneath the Place of Magic (12 of them)', NULL, NULL, NULL, 'A small flesh-eating worm that bores into living victims; a dozen lie buried in a wood pile at the tunnel entrance. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.182'),
('minotaur-old-ones', 'Minotaur', 'humanoid', 'palladium-fantasy', 0, 'Miscreant', '{"IQ":"6","Spd":"20"}', '2D6+26', NULL, NULL, NULL, NULL, 'Hit Points printed as 2-12+26.', 12, NULL, '{"attacks":2,"strike":2,"parry":2,"dodge":2,"damage":6}', 'First-edition figures, as printed. Printed as "Typical Minotaur". Half damage from fire or cold. Spells: none. Weapon proficiencies (pick just one): Large sword +4 strike, +4 parry, +2 thrown; Blunt +4 strike, +3 parry, +2 thrown. Weapons by percentile: 1-30 long sword, 31-60 mace, 61-90 club, 91-00 hercules club. Possessions: very little, a few bits of clothing. Young have 1/2 adult attributes.', 'Languages include troll and goblin (30%).', 'Claws, a horn charge, 60 ft nightvision, and resistance to heat and cold.', NULL, NULL, NULL, NULL, NULL, 'Rooms T-33 through T-44 of the tunnels beneath the Place of Magic; the tribe is 16 adult males, 14 adult females, 6 young and 2 infants', 'Caliph Alsto Stone; other minotaurs', NULL, NULL, 'Bull-headed, dark-skinned servants of Alsto with glowing yellow-orange eyes; slow-witted but sensible enough to fall back, fetch help or yield, and more faithful to each other than to their master. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.188'),
('zombie-of-artimus', 'Zombie of Artimus', 'undead', 'palladium-fantasy', 0, NULL, '{"IQ":"4","PS":"20","Spd":"8"}', '15D6', NULL, NULL, NULL, NULL, 'Printed as 15-90 hit points. Eight in room M-42 are printed at 43, 51, 37, 70, 62, 49, 54 and 65 hit points; one locked in room M-57 has 72.', NULL, NULL, '{"attacks":2,"damage":5}', 'First-edition figures, as printed. +3 on all saves. Half damage from fire and cold; charm has no effect; damaged by silver, holy or magic only.', NULL, 'Takes only half harm from flame or frost, shrugs off charms, and can be wounded only with silver, holy or enchanted weapons. It can say nothing except one set warning, recited in Western.', NULL, NULL, NULL, NULL, NULL, 'The Dwarven Complex of the Place of Magic, rooms M-35 through M-51; at least one in every corridor', 'Artimus Gordon, their maker', NULL, NULL, 'The wizard Artimus Gordon''s walking dead. They leave intruders alone unless ordered or struck, deliver their warning in chorus, then walk back to room M-39 to report. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.199');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('aprek-nar', 'Aprek-Nar', NULL, 'Hidden Demon Lord of Credia', 'palladium-fantasy', 'Demon Lord', NULL, NULL, 'Diabolic', NULL, '65 ft tall', NULL, NULL, 380, NULL, NULL, NULL, NULL, 14, NULL, '{"strike":1,"damage":5}', 'First-edition figures, as printed. +6 on all saving throws. A.R. 14 is printed with no armour, so it is his own. The Number of Attacks line lists the three attack forms but prints no count per melee.', NULL, NULL, NULL, 'None (printed: No Magic or Psionics).', 'None (printed: No Magic or Psionics).', NULL, NULL, NULL, NULL, 'Dim-witted brute.', NULL, NULL, 'One of five demon lords said to be bound somewhere beneath the capital city of Credia; a towering, shaggy, ape-like giant of little wit. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.34'),
('rebob', 'Rebob', NULL, 'Hidden Demon Lord of Credia', 'palladium-fantasy', 'Demon Lord', '12th level Warlock', 12, 'Aberrant', NULL, '6 ft tall', NULL, NULL, 210, NULL, NULL, NULL, 155, 12, NULL, '{"attacks":2,"strike":4,"damage":8}', 'First-edition figures, as printed. +8 on all saving throws. A.R. 12 is printed with no armour, so it is his own. Dimensional teleport 85%. Clerical abilities: none.', NULL, NULL, 'Sees in the dark, can turn invisible, flies at 40 mph, takes no damage from fire or cold, and can teleport between dimensions (85%).', '12th level Warlock, all Fire Elemental Spells.', 'All level one and two abilities, I.S.P. 155, 7th level proficiency.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'One of five demon lords said to be bound somewhere beneath the capital city of Credia; a man-sized demon with leathery wings who is always turned out in black evening clothes and a frilled white shirt. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.34'),
('grombeer', 'Grombeer', NULL, 'Hidden Demon Lord of Credia', 'palladium-fantasy', 'Demon Lord', '10th level Warlock', 10, 'Diabolic', NULL, '30 ft tall', NULL, NULL, 340, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":2}', 'First-edition figures, as printed. A.R. 12 is printed with no armour, so it is his own. Invulnerable to magic. Clerical abilities: none.', NULL, NULL, 'Magic cannot harm him.', 'All Earth Elemental Spells, 10th level Warlock.', 'None.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'One of five demon lords said to be bound somewhere beneath the capital city of Credia; he resembles a misshapen elemental of earth and stone. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.35'),
('lemerhop', 'Lemerhop', NULL, 'Hidden Demon Lord of Credia', 'palladium-fantasy', 'Demon Lord', NULL, NULL, 'Miscreant', NULL, '30 ft in diameter', NULL, NULL, 260, NULL, NULL, NULL, NULL, 18, NULL, NULL, 'First-edition figures, as printed. A.R. 18 is printed with no armour, so it is his own. Invulnerable to any physical attacks. No count of attacks per melee is printed.', NULL, NULL, 'No physical attack of any kind can hurt him.', 'Control of ALL Undead Creatures.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'One of five demon lords said to be bound somewhere beneath the capital city of Credia; a bank of green mist speckled with small wavering lights that harms whoever it swallows. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.35'),
('wsitrab', 'Wsitrab', NULL, 'Hidden Demon Lord of Credia', 'palladium-fantasy', 'Demon Lord', NULL, NULL, 'Diabolic', NULL, '25 ft tall', NULL, NULL, 780, NULL, NULL, NULL, NULL, 8, NULL, NULL, 'First-edition figures, as printed. A.R. 8 is printed with no armour, so it is his own. Attacks per melee: 1 out of water, 4 in the water (against anyone within 30 ft). Full Regeneration.', NULL, NULL, 'Regenerates fully. Far more dangerous when submerged than on land.', 'Complete control of Water Spells and Water Elementals.', NULL, NULL, NULL, NULL, NULL, 'Makes for deep water whenever he can.', NULL, NULL, 'One of five demon lords said to be bound somewhere beneath the capital city of Credia; a gigantic squid-shaped thing with one eye and one tentacle. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.35'),
('drusila', 'Drusila', NULL, 'Entombed vampire of Credia', 'palladium-fantasy', 'Vampire', '4th level Mind Mage, 4th level Warlock, 4th level Summoner, 5th level Assassin', 5, NULL, NULL, NULL, NULL, NULL, 96, NULL, NULL, NULL, 85, 12, NULL, NULL, 'First-edition figures, as printed. A.R. 12 is printed with no armour named. Other abilities standard for Vampires. Needs 8 rounds to push open the stone block sealing his crypt once he starts.', NULL, NULL, NULL, '4th level Warlock, 4th level Summoner; spells and circles not listed.', '4th level Mind Mage with 85 I.S.P.; powers not listed.', NULL, NULL, NULL, NULL, 'Patient while trapped; once loose he feeds on the first fit young person in sight and then runs.', NULL, NULL, 'A vampire lying in a hidden tomb somewhere in Credia, a small chamber with twelve crypts, whose stake rotted away long ago; he waits for someone to break in from outside. The book calls Drusila he. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.35'),
('antipator', 'Antipator', NULL, 'Fallen Devil Lord of Antipator''s Chapel, Credia', 'palladium-fantasy', 'Devil', NULL, NULL, 'Aberrant (evil)', NULL, '7 ft tall', NULL, '{"IQ":22,"ME":24}', 343, NULL, NULL, NULL, 130, 14, NULL, '{"attacks":3}', 'First-edition figures, as printed. Attacks are 3 claws, or by weapon, by magic or by psionics. A.R. 14 is printed for Antipator himself. Teleport 98%, bio-regeneration (3-18). Clerical abilities: turn 100-200 dead 80%, exorcism 60%, curse 50%, remove curse 80%, healing touch (3-18), resurrection 40%, dimensional teleport 85%, summon minions (1-3 Beasts) 98%. Staff of Power is +3 to hit.', NULL, 'Knows all languages.', 'Nightvision to 120 feet, resists fire and cold, teleports (98%), regenerates 3-18, and speaks every language.', 'All spell magic, levels 1-5 at 6th level proficiency.', 'All levels, I.S.P. 130, 10th level proficiency.', NULL, NULL, 'Antipator''s Staff of Power (4-24 damage, +3 to hit, 10% chance of paralyzation, automatically intimidates any evil creature with less than 120 hit points); Eye of Antipator (any one Earth Elemental Magic Spell a day); Holy Armour of Antipator (A.R. 18, S.D.C. 343, self-regenerating 3-18 S.D.C./round, wearer performs as a first level Palladin of Antipator).', NULL, 'Wants his cult rebuilt and demands a human sacrifice before he will anoint anyone; refusal earns curses and, if pressed, death.', 'His attendant Beasts Altophena, Milenda and Wolendia', NULL, 'A former god and Devil Lord, now ranked among the Greater Devils, confined to a secret underground chapel in Credia until a bishop and enough worshippers restore his sect. He shows himself as a fair-haired elf with fangs, horns, a tail and hooves. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.35'),
('arat-beastslayer', 'Arat Beastslayer', 'Flavius Draconius', 'Gladiator of the Wolf Pit, Credia''s Public Arena', 'palladium-fantasy', 'Wolfen', '10th level Knight, 7th level Assassin', 10, 'Anarchist', NULL, NULL, NULL, '{"IQ":12,"ME":14,"MA":9,"PS":25,"PP":24,"PE":19,"PB":9,"Spd":17}', 82, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":4,"strike":5,"parry":8,"dodge":8,"damage":14}', 'First-edition figures, as printed. Stuns on 18-20, critical strike 17-20, critical strike from behind (X3). +5 is printed as ''to hit''. Alignment is printed as anarchist (selfish), changed from principled.', NULL, '9th level Weapon Proficiency in ALL weapons except Pole Arms (15th level) and Bows (6th level).', NULL, NULL, 'None.', NULL, NULL, NULL, NULL, 'Embittered by years of being handled as a beast; accepts wine and food as bribes from the bookmakers and toughs, and loathes them above all others.', NULL, NULL, 'A Wolfen knight from the northern wilds, taken captive and kept alive nine years in the wolf pit of the public arena in Credia''s Main Plaza, penned with a pack of wild wolves. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.38'),
('tansaburon-the-fire-dragon', 'Tansaburon the Fire Dragon', NULL, 'Dragon of the Dragon Pits, Credia''s Public Arena', 'palladium-fantasy', 'Fire Dragon', NULL, NULL, NULL, 'Over 6500 years', NULL, NULL, NULL, 68, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Only hit points, age and length are printed; no A.R., attacks or bonuses.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Sleeps on a small hoard of gold, silver and copper gathered from the arena crowds; no amount printed.', 'Old and drowsy, content to doze on his coins between feedings.', NULL, NULL, 'An aged red-winged dragon, 78 feet in length, nearly sightless and shedding teeth, who settled in the pits of Credia''s public arena over three centuries ago and is fed tied-up prisoners or cattle roughly once a month. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.38'),
('brother-bear', 'Brother Bear', 'Klii Tang', 'Druid and town council leader of Arian', 'palladium-fantasy', 'Human', '7th level Druid', 7, 'Miscreant', NULL, NULL, NULL, '{"IQ":9,"ME":8,"MA":9,"PS":9,"PP":10,"PE":14,"PB":9,"Spd":11}', 40, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3,"parry":5,"dodge":5,"damage":6}', 'First-edition figures, as printed. Attacks are 3 hand to hand or via animal control. +5 is printed as ''to parry or dodge''; the bonuses include hand to hand: mercenary skill and totem bonuses. A.R. 12 is his studded leather armour (S.D.C. 38). Totem animal is canine.', '[{"name":"Medical","pct":86},{"name":"Prowl","pct":62},{"name":"Identify tracks","pct":83},{"name":"Track","pct":79},{"name":"Befriend animals (1-4)","pct":80},{"name":"Calm animals (1-4 per level)","pct":78},{"name":"Control animals (1-4 per level)","pct":62},{"name":"Summon totem animal (general)","pct":72},{"name":"Summon totem animal (specific)","pct":64},{"name":"Speaks southern, western, goblin and elven","pct":100}]', 'Medical is printed 86/90%. Horsemanship: Knight, no percentage printed. Metamorphosis into totem animal, no percentage printed.', NULL, 'Druid abilities: identify tracks 83%, track 79%; effects on animals: befriend (1-4) 80%, calm (1-4 per level) 78%, control (1-4 per level) 62%; summon totem animal 72% (general), 64% (specific); metamorphosis into totem animal.', NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38). All-wood weapons: staff, short bow, stone axe. Soft leather and animal-skin clothing, simple furnishings, smoking tobacco and pipe, various herbs, 4 doses of hemlock poison, half a pound of dried hallucinagenic mushrooms, one dozen unscented candles, one lantern, personal items.', 'Emerald ring (worth 1000 gold), 450 in gold coins and 180 in silver.', 'Sly and scheming, a quiet man who likes being feared and having others under his thumb.', 'His fox familiar Tag, the bears Big Brother and Little Brother, and his kennel of dogs and a wolf. Animal companion: Tag (silver fox, 19 hit points; +5 dodge, +2 damage; bite 1-4; prowl 50%; track 60%; swim 40%). Animal companion: Big Brother (giant brown bear, 62 hit points; 2 attacks per melee, +2 strike, +6 damage; bite 1-8; claws 2-12). Animal companion: Little Brother (mountain brown bear, 50 hit points; 2 attacks per melee, +2 strike, +6 damage; bite 1-6; claws 1-8).', NULL, 'The druid on the town council of Arian and the true power there; trappers whisper that he hunts people in wolf or coyote shape. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.63-65'),
('tabor-samila', 'Tabor Samila', NULL, 'Head of the town council of Arian', 'palladium-fantasy', 'Human', '5th level Air Warlock', 5, 'Anarchist', NULL, NULL, NULL, '{"IQ":13,"ME":11,"MA":12,"PS":13,"PP":9,"PE":9,"PB":13,"Spd":10}', 39, NULL, NULL, NULL, NULL, 13, NULL, '{"attacks":1}', 'First-edition figures, as printed. Attacks are 1 hand to hand or 2 spells. +1 spell strength, +1 save vs. spells, circles and wards. A.R. 13 is his chain mail (S.D.C. 44).', '[{"name":"Play Wind Instrument","pct":66},{"name":"Swim","pct":80},{"name":"Speaks goblin, dwarven, southern","pct":100}]', 'W.P. Blunt, W.P. Crossbow.', NULL, '10 spells daily: Create Light, Stop Wind, Change Wind Direction, Silence (15ft), Call Lightning, Darkness, Calm Storms, Invisibility, Detect the Invisible, Breath of Life; 25% chance of summoning a lesser air elemental.', NULL, NULL, NULL, 'Chain mail (A.R. 13, S.D.C. 44); 2 knives, morning star, flail, cross bow; personal items, a flute, snuff, scroll of reduce object.', '1400 in gold coins, a diamond ring (worth 2200 gold), 3 small sapphires worth 200 gold each.', 'Amiable but somewhat haughty, a rich dresser who is no pushover yet is cowed by the druid he is afraid of.', 'The town council and its 24 hired mercenaries', 'Bandits in the woods around Arian', 'The warlock who officially heads the town council of Arian, a border town in the Old Kingdom, though Brother Bear overshadows him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.65'),
('captain-estaban-el-carlo', 'Captain Estaban El-Carlo', NULL, 'Town council member of Arian', 'palladium-fantasy', NULL, '8th level Soldier', 8, 'Scrupulous', NULL, NULL, NULL, '{"IQ":9,"ME":6,"MA":6,"PS":13,"PP":12,"PE":8,"PB":9,"Spd":7}', 56, NULL, NULL, NULL, NULL, 15, NULL, '{"attacks":3,"parry":3,"dodge":3,"damage":4}', 'First-edition figures, as printed. Plus W.P. bonuses. A.R. 15 is his plate and chain armour (S.D.C. 100). No race is printed in the block.', '[{"name":"Read/write western","pct":62},{"name":"Speaks western, southern, eastern and elven","pct":100}]', 'Horsemanship: general, W.P. Large Sword, W.P. Pole Arm, W.P. Knives, W.P. Small Shield.', NULL, NULL, NULL, NULL, NULL, 'Plate and chain (A.R. 15, S.D.C. 100); military fork, sabre halberd, broad sword, 2 knives; extra chain mail armour (A.R. 14, S.D.C. 55), goupillon flail, small shield, western silks, cloth, pint of western brandy. War horse Nightshade.', '200 gold and 50 silver coins.', 'Courteous and mild, but edgy and easily startled when strangers are about.', 'His war horse Nightshade. Animal companion: Nightshade (war horse, 51 hit points; barding (a.r. 14, s.d.c. 70); worth about 45,000 gold).', NULL, 'A soldier and noble from the west who arrived in Arian five years ago and sits on its town council; talk has it he is a fugitive from the Western Empire. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.65'),
('father-tarka', 'Father Tarka', 'Kra Guerla', 'Head of the town council of Baca', 'palladium-fantasy', 'Human', '6th level Priest of Tark, the Spider Goddess', 6, 'Miscreant', '34', NULL, NULL, '{"IQ":11}', 39, NULL, NULL, NULL, NULL, 9, NULL, '{"attacks":1}', 'First-edition figures, as printed. Attacks are 1 hand to hand or 2 spells. +1 spell strength, +1 save vs. spells, circles, wards. A.R. 9 is his soft leather armour (S.D.C. 20). Other attributes are average (not printed).', '[{"name":"Read/write southern","pct":100},{"name":"Speak southern, goblin, elven","pct":100}]', 'W.P. Staves, W.P. Knives.', NULL, '8 spells per day: Decipher Magic, Cloud of Slumber, Invisibility (self), Fly as an Eagle, Armour of Ithan, Call Lightning, Teleport (self), Diminish Others, plus clerical abilities.', NULL, NULL, NULL, 'Soft leather armour (A.R. 9, S.D.C. 20); iron staff, short sword and knives; personal items, clothes, 4 blank books, 48 sheets of parchment, inks, pens, charcoal, incense, 36 scented candles, scroll of remove curse.', '240 gold in his room, ruby ring (approx. value 2200 gold), 4600 gold hidden in the torture chamber.', 'Distrustful of everybody, a smooth and crafty liar who wipes out anyone he thinks might endanger his scheme.', 'The five Baca councilmen, the council''s 36 mercenaries, and the ogres he trades with', NULL, 'A priest from the Yin-Sloth Jungles who runs Baca''s town council and secretly sells contraband supplies to ogre caravans. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.66'),
('brutus-leetee', 'Brutus Leetee', NULL, 'Councilman of Baca', 'palladium-fantasy', 'Human', '5th level Noble', 5, 'Anarchist', '28', NULL, NULL, '{"IQ":10,"PE":12,"PB":12}', 28, NULL, NULL, NULL, NULL, 14, NULL, '{"attacks":3,"parry":3,"dodge":3,"damage":2}', 'First-edition figures, as printed. A.R. 14 is his double mail (S.D.C. 55). Other attributes are average (not printed).', '[{"name":"Read/write southern","pct":100},{"name":"Speaks southern and goblin","pct":100}]', 'W.P. Large Sword, W.P. Short Sword, W.P. Knife, Horsemanship: knight.', NULL, NULL, NULL, NULL, NULL, 'Double mail (A.R. 14, S.D.C. 55); bastard sword, short sword and knife; extra bastard sword and knife, attractive furnishings, expensive clothes, misc. personal items.', '750 gold hidden in the house; a silver pendant of a serpent (worth 100 gold) and an emerald ring (worth 600 gold).', 'Chatty and pleasant on the surface, privately ambitious and touchy about being made fun of.', 'Father Tarka and the Baca town council', NULL, 'An unmarried young noble on the corrupt town council of Baca, party to its secret ogre trade. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.66-68'),
('bernard-tyro', 'Bernard Tyro', NULL, 'Councilman of Baca', 'palladium-fantasy', 'Elf', '8th level Scholar', 8, 'Miscreant', '50', NULL, NULL, '{"IQ":14,"MA":4,"PP":14,"PB":20}', 30, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Distant and conceited, wrapped up in his own business and fond of good drink and revelry.', 'Father Tarka and the Baca town council', NULL, 'An elf from the East who sits on the corrupt town council of Baca. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.68'),
('samual-calder', 'Samual Calder', NULL, 'Councilman of Baca', 'palladium-fantasy', 'Human', '8th level Merchant (retired)', 8, 'Diabolic', '57', NULL, NULL, '{"IQ":11,"PE":12}', 44, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A jovial, sociable plotter with a taste for wagers and risk.', 'Father Tarka and the Baca town council', NULL, 'A retired merchant on the corrupt town council of Baca who owns the town''s wagonsmith. The block heads him Samual; elsewhere the book spells it Samuel. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.68'),
('craig-topenda', 'Craig Topenda', NULL, 'Councilman of Baca', 'palladium-fantasy', 'Human', '5th level Merchant', 5, 'Anarchist', '37', NULL, NULL, '{"IQ":10}', 33, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Nasty, distrustful and quick to hold a grudge; likes to gamble.', 'Father Tarka and the Baca town council', NULL, 'A merchant on the corrupt town council of Baca who owns the town slaughterhouse. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.68'),
('arvell-mundune', 'Arvell Mundune', NULL, 'Councilman of Baca', 'palladium-fantasy', 'Human', '4th level Ranger, 3rd level Merchant', 4, NULL, '34', NULL, NULL, '{"IQ":10,"PS":12,"PE":14}', 41, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. No alignment is printed. Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A chatty, hard-bitten former trapper who is wary of people and bears grudges.', 'Father Tarka and the Baca town council', NULL, 'A councilman of Baca who owns and runs the Trappers Snare fur shop there. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.68'),
('thush-borgn', 'Thush Borg''n', NULL, 'Healer of the Churgery, Hanna', 'palladium-fantasy', 'Ogre', 'Healer', NULL, 'Anarchist', NULL, NULL, NULL, '{"IQ":9,"PS":24,"PE":22}', 43, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. No level is printed; the entry calls him a freed ogre healer.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Even-tempered about frightened strangers; fights only as hard as he must to end an assault and then patches up the attacker for a small fee.', NULL, 'Imorncilus Westerling, priest of the Temple of Light in Hanna', 'A freed ogre who runs the Churgery, the town hospital of Hanna, and is accepted by most locals. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.82'),
('aras-dwelve', 'Aras Dwelve', NULL, 'Scrivener of the Pit and cult leader, Hanna', 'palladium-fantasy', 'Human', '4th level Priest of Darkness', 4, 'Aberrant', NULL, NULL, NULL, NULL, 26, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Normally wears no armour; owns a suit of hard leather (A.R. 10, S.D.C. 30).', NULL, NULL, NULL, '5 spells per day: Cloud of Slumber, Invisibility, Mesmerism, Fly as an Eagle, Mystic Illusion.', NULL, NULL, NULL, 'Battle axe, 2 knives; a suit of hard leather (A.R. 10, S.D.C. 30), normally not worn.', NULL, 'Passes for a gentle, open-handed scribe, which is a front.', 'The outlawed cult of Aco and the Juggernaut', NULL, 'A scribe at the sign of the Pen and Hand in Hanna''s slum who secretly leads a banned cult that sacrifices people at a hidden altar under his workroom. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.84-86'),
('sir-arin-gatik', 'Sir Arin Gatik', 'Arin Gatik', 'The Viper; knight and lord of the town of Tanith', 'palladium-fantasy', 'Human', '12th level Mercenary', 12, 'Aberrant', '72', NULL, NULL, NULL, 77, NULL, NULL, NULL, NULL, 17, NULL, '{"attacks":4,"strike":3,"parry":4,"dodge":4,"damage":4}', 'First-edition figures, as printed. Attacks are 4 hand to hand. The printed bonuses include his P.P. bonus but not all hand to hand or W.P. bonuses. A.R. 17 is his magic light-weight plate (S.D.C. 200); he is usually dressed in a leather vest instead (A.R. 6, S.D.C. 10). The stat block prints Age 72; the town text on p.108 gives seventy-four. The block spells his alignment Abberant.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic light-weight plate (A.R. 17, S.D.C. 200); leather vest (A.R. 6, S.D.C. 10) and fine clothing; flamberge, military fork, morning star, knives, large magic dagger (returns to the thrower, indestructible, gold plated handle).', NULL, 'Genial and even-handed with everybody in town, hiding a ruthless old raider underneath.', 'Old Melthan, the elf air warlock who runs the trade exchange; his loyal mercenaries; visiting smugglers', NULL, 'The aged lord of the farm town of Tanith, once the masked border raider called the Viper and widely thought dead under that name. He secretly runs a smuggling ring out of the ruined prison dungeons near his home, while the townsfolk credit him with keeping its ghosts quiet. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.110'),
('sir-lawrence-the-red', 'Sir Lawrence the Red', 'Lawrence Partha', 'Captain of Fort Aberla', 'palladium-fantasy', 'Human', '4th level Knight', 4, 'Unprincipled', '29', NULL, NULL, '{"IQ":9,"PS":12,"PP":14,"PE":14}', 27, NULL, NULL, NULL, NULL, 17, NULL, NULL, 'First-edition figures, as printed. A.R. 17 is his plate armour (S.D.C. 160). Other attributes are average (not printed).', '[{"name":"Read/write Southern","pct":58},{"name":"Speaks Southern","pct":100},{"name":"Speaks Elven, Western, Eastern","pct":80}]', 'Horsemanship (knight), W.P. Lance, W.P. Blunt, W.P. Short Sword.', NULL, NULL, NULL, NULL, NULL, 'Plate armour (A.R. 17, S.D.C. 160). A war horse (the fort keeps two, the captain''s and the lieutenant''s, approx. 20,000 gold each).', NULL, 'Able, sharp and honourable, yet lonely and unsure of himself.', NULL, NULL, 'Commander of Fort Aberla, the Type III fort guarding the Aberla Mountain Pass. His rich noble father purchased the post for him and many of the garrison wrongly think him a coward, though he would die before abandoning the fort or his soldiers. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.120'),
('lieutenant-fuunt-proteela', 'Lieutenant Fuunt Proteela', NULL, 'Lieutenant of Fort Aberla', 'palladium-fantasy', 'Elf', '6th level Longbowman', 6, 'Anarchist', '78', NULL, NULL, '{"IQ":12,"MA":7,"PS":12,"PP":20,"PE":11,"PB":26}', 43, NULL, NULL, NULL, NULL, 15, NULL, NULL, 'First-edition figures, as printed. A.R. 15 is his scale mail (S.D.C. 75). Other attributes are average (not printed).', '[{"name":"Forgery","pct":58},{"name":"Prowl","pct":52},{"name":"Speaks Elven, Southern, Dwarven, Western","pct":100},{"name":"Speaks Goblin","pct":55}]', 'Forgery is printed 58/28%. W.P. Long bow, Horsemanship (general).', NULL, NULL, NULL, NULL, NULL, 'Scale mail (A.R. 15, S.D.C. 75). A war horse (approx. 20,000 gold).', NULL, 'Haughty, hard and insolent, sure of himself; has no love for dwarves or nobles and begrudges the Captain a command he thinks ought to be his own.', NULL, NULL, 'Second in command at Fort Aberla, and the officer the rank and file actually turn to for direction. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.120'),
('sgt-mike-beeg', 'Sgt. Mike Beeg', NULL, 'The Thunderer, Sergeant of Fort Aberla', 'palladium-fantasy', 'Human', '4th level Air Warlock', 4, 'Miscreant', '24', NULL, NULL, '{"IQ":9,"ME":10,"PE":12}', 34, NULL, NULL, NULL, NULL, 12, NULL, NULL, 'First-edition figures, as printed. A.R. 12 is his studded leather armour (S.D.C. 38). Other attributes are average (not printed).', '[{"name":"Speaks Southern, Goblin","pct":100},{"name":"Speaks Elven and Dwarven","pct":60}]', 'W.P. Knives, W.P. Short Sword.', NULL, '4th level Air Warlock, 8 spells daily: Clap of thunder, cloud of steam, change wind direction, wind rush, call lightning, 15ft. air bubble, protection from lightning, invisibility. Summon lesser elemental 20%.', NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38).', NULL, 'A plotter and risk-taking gambler forever angling for an advantage; dislikes every non-human race apart from elves.', NULL, NULL, 'An air warlock sergeant in the Fort Aberla garrison, known by the nickname the Thunderer. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.121'),
('staff-sgt-rocky-gra', 'Staff Sgt. "Rocky" Gra', NULL, 'Staff Sergeant of Fort Aberla', 'palladium-fantasy', 'Orc', '4th level Earth Warlock', 4, 'Scrupulous', '26', NULL, NULL, '{"IQ":7,"ME":5,"PS":21,"Spd":12}', 29, NULL, NULL, NULL, NULL, 13, NULL, '{"damage":6}', 'First-edition figures, as printed. +6 to damage is printed beside his P.S. A.R. 13 is his chain mail (S.D.C. 44). Other attributes are average (not printed).', '[{"name":"Speaks Goblin, Elven, Dwarven","pct":100},{"name":"Speaks Ogre","pct":60}]', 'W.P. Blunt, W.P. Sling. Can''t read/write.', NULL, '4th level Earth Warlock, 8 spells daily: Dust storm, chameleon, track, dowsing, wall of stone, encase object in stone, mend stone, quick sand. Summon lesser elemental 20%.', NULL, NULL, NULL, 'Chain mail (A.R. 13, S.D.C. 44).', NULL, 'Relaxed, sociable and unbothered by the contempt most human troopers show him; faithful to fort, crown and Captain.', 'The elves of Fort Aberla, who would avenge him (he does not know it)', NULL, 'An orc earth warlock serving at Fort Aberla. His friendship with the fort''s elves irritates the humans who mistreat him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.121'),
('high-priestess-zeetana', 'High Priestess Zeetana', NULL, 'High Priestess of Ra at Fort Aberla', 'palladium-fantasy', 'Human', '5th level Priestess of Ra', 5, 'Unprincipled', '30', NULL, NULL, '{"IQ":10,"PB":12,"Spd":14}', 38, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. No armour printed. Other attributes are average (not printed).', '[{"name":"Speaks Western, Southern","pct":100},{"name":"Speaks Goblin and Elf","pct":65}]', 'W.P. Blunt, W.P. Knives, Horsemanship (general).', NULL, '5th level priestess, 5 spells daily: Cloud of slumber, firey touch, extinguish fires, call lightning, breath of life.', NULL, NULL, NULL, NULL, NULL, 'Self-contained, cool and remote, wary of others to the point of mild paranoia.', 'The 2-8 second level priests of Ra and the pantheon of light she leads at the fort', 'Bounty hunters; a price of 50,000 Western gold is on her head', 'Head of the priests stationed at Fort Aberla. She seldom sets foot outside because the Western Empire wants her for killing a noble. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.121'),
('captain-lee-carter', 'Captain Lee Carter', NULL, 'Captain of Fort Alandia', 'palladium-fantasy', 'Human', '7th level Knight', 7, 'Scrupulous', '47', NULL, NULL, '{"IQ":10,"ME":7,"MA":11,"PS":12,"PP":14,"PE":15,"PB":16,"Spd":8}', 63, NULL, NULL, NULL, NULL, 16, NULL, '{"attacks":3,"damage":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. W.P. bonuses are not included in the printed bonuses. A.R. 16 is his splint armour (S.D.C. 82). Lee Carter is noted as his true name; native of Timiro.', '[{"name":"Scale Walls","pct":68},{"name":"Recognize Weapon Quality","pct":72},{"name":"Speaks Southern","pct":100},{"name":"Speaks Elven, Goblin and Eastern","pct":80},{"name":"Read/write Southern","pct":76}]', 'Horsemanship (knight), W.P. Large Shield, W.P. Lance, W.P. Large Sword, W.P. Blunt.', NULL, NULL, NULL, NULL, NULL, 'Splint armour (A.R. 16, S.D.C. 82); lance, bastard sword, horseman hammer, throwing axe, two knives, large shield. Also a book of poems and a book on the history and legends of the gods of light and dark (both written in Southern), a suit of hard leather armour, jade statue of Isis (800 gold), clothes, riding gear, leather and chain barding, misc. personal items, pint of Western brandy. War horse named Silver, worth 20,000 gold, 41 hit points.', '900 gold.', 'A soft-spoken, tired old campaigner who is kind, even-handed and truthful.', 'Lieutenant K''m Nisto, his closest friend; the veteran mercenaries of the fort', NULL, 'Commands the 72 mercenaries of Fort Alandia, a wooden Type II fort up at the north end of Timiro''s frontier. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.122'),
('lieutenant-km-nisto', 'Lieutenant K''m Nisto', NULL, 'Lieutenant of Fort Alandia', 'palladium-fantasy', 'Elf', '5th level Long Bowman', 5, 'Unprincipled', '36', NULL, NULL, '{"IQ":10,"PS":12,"PP":15,"PB":18,"Spd":11}', 44, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. No armour printed. Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Devoted to Captain Carter above all.', 'Captain Lee Carter', NULL, 'An elven archer officer at Fort Alandia, given only as a note under the captain whose best friend he is. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.122'),
('sir-leonard-balasco', 'Sir Leonard Balasco', NULL, 'Commander of Fort Areal', 'palladium-fantasy', 'Elf', '7th level Knight', 7, 'Principled', '50', NULL, NULL, '{"IQ":12,"PS":14,"PP":21,"PE":12,"PB":19}', 41, NULL, NULL, NULL, NULL, 15, NULL, '{"strike":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. The +3 to strike, parry and dodge is printed beside his P.P. A.R. 15 is his scale mail (S.D.C. 75). Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Scale mail (A.R. 15, S.D.C. 75).', NULL, 'Polite, welcoming and just.', NULL, NULL, 'Officer in charge of Fort Areal, a stone Type II fort and border patrol base with 124 soldiers. Printed as Elven. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.122'),
('sir-rapheal-renko', 'Sir Rapheal Renko', NULL, 'Captain of the elite Sentinels, Fort Areal', 'palladium-fantasy', 'Human', '4th level Palladin', 4, 'Aberrant', '27', NULL, NULL, '{"IQ":10,"PS":12,"PP":13,"PE":20}', 32, NULL, NULL, NULL, NULL, 17, NULL, NULL, 'First-edition figures, as printed. +3 vs. magic/poison (printed beside his P.E.). A.R. 17 is his black plate armour (S.D.C. 150). Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Black plate armour (A.R. 17, S.D.C. 150).', NULL, 'Obsessed with honour and discipline, hard, self-reliant and without fear in a fight; asks nothing of his riders that he will not do first.', NULL, NULL, 'Leads the 48 noble-born Sentinel cavalry of Fort Areal, who give him total loyalty. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.122'),
('captain-shadow-stalker', 'Captain Shadow Stalker', 'Kryle Latry', 'Captain of Fort Bext', 'palladium-fantasy', 'Changeling', '6th level Assassin', 6, 'Anarchist', '56 (appears to be a human of about 36)', NULL, NULL, '{"IQ":10,"ME":15,"MA":9,"PS":15,"PP":15,"PE":4,"PB":6,"Spd":6}', 31, NULL, NULL, NULL, NULL, 14, NULL, '{"attacks":3,"damage":2}', 'First-edition figures, as printed. Critical strikes: see Assassin combat. W.P. bonuses not included. A.R. 14 is his double mail (S.D.C. 55).', '[{"name":"Scale Walls","pct":71},{"name":"Use Poison","pct":63},{"name":"Recognize Poison","pct":65},{"name":"Prowl","pct":68},{"name":"Pick Pockets","pct":45},{"name":"Imitate Voices","pct":66},{"name":"Recognize Precious Stones","pct":55},{"name":"Speaks Elven","pct":100},{"name":"Speaks Eastern and Southern","pct":95},{"name":"Speaks Troll","pct":75},{"name":"Read and write Elven","pct":60}]', 'Horsemanship (general), W.P. Pole arm, W.P. Ball and Chain, W.P. Knives, W.P. Short Sword.', NULL, NULL, NULL, NULL, NULL, 'Double mail (A.R. 14, S.D.C. 55); sabre halberd, five knives, goupillon flail, nunchaku, cutlass. Several sets of clothing, boots, riding gear, saddle, misc. personal belongings. Hidden in his quarters: a silver cross, a pearl handled throwing knife and a Scroll of strength of Utgard-Loki.', '853 gold hidden in his personal quarters.', 'Unruffled and commanding, fiercely guards his troops and his post; devoted to King, country and himself. His men adore him.', 'The 72 mercenaries of Fort Bext', NULL, 'A changeling passing as a tall, lean, dark human who leads the celebrated mercenary band holding Fort Bext at the Ibera Mountain Pass. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.123'),
('pdar-the-troll', 'P''dar the Troll', NULL, 'Corporal of Fort Bext', 'palladium-fantasy', 'Troll', '4th level Mercenary Fighter', 4, 'Anarchist', '28', '11 ft', NULL, NULL, 37, NULL, NULL, NULL, NULL, 13, NULL, '{"attacks":2,"damage":11,"strike":2,"parry":2,"dodge":2}', 'First-edition figures, as printed. +3 vs. magic/poison. W.P. bonuses not included. A.R. 13 is his chain mail (S.D.C. 44). P''dar is noted as his true name. No attributes printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Chain mail (A.R. 13, S.D.C. 44); giant sized weapons: hippe, flamberge, short sword, 3 knives, sling. Also 3 spears, broad sword, another suit of armour (studded leather), large shield, clothing, 10 lbs. of rock candy, an emerald (1000 gold) and 24 skulls of various races.', '200 gold.', 'Detests the sergeant called the Whip and makes sure he behaves.', NULL, 'The Whip (Grunn Mitt)', 'A troll corporal among the Fort Bext mercenaries, one of the few garrisons where his kind is treated as an equal. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.123'),
('the-whip-grunn-mitt', 'The Whip', 'Grunn Mitt', 'Sergeant of Fort Bext', 'palladium-fantasy', 'Orc', '3rd level Thief', 3, 'Miscreant', '20', NULL, NULL, '{"IQ":8,"ME":10,"MA":9,"PS":20,"PP":19,"PE":12,"PB":8,"Spd":14}', 34, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":2,"damage":5,"strike":2,"parry":2,"dodge":2}', 'First-edition figures, as printed. W.P. bonuses not included. A.R. 12 is his studded leather armour (S.D.C. 38).', '[{"name":"Scale Walls","pct":48},{"name":"Disguise","pct":35},{"name":"Pick Pocket","pct":42},{"name":"Prowl","pct":45},{"name":"Pick Locks","pct":30},{"name":"Recognize Poison","pct":40},{"name":"Speaks Goblin","pct":100},{"name":"Speaks Southern","pct":70}]', 'Disguise is printed 35/11%.', NULL, NULL, NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38); bull whip, cat-o-nine tails, hand pick, 4 daggers, mace and chain. Also another bull whip, rope, clothes, rum (4 gallons), lock picking tools, 2 potions of healing.', '430 gold.', 'Jolly on the surface but vicious and boastful; relishes rank and would torture prisoners if his captain let him. Unpopular, though a ruthless fighter who stays true to the captain.', NULL, 'P''dar the Troll', 'An orc thief serving as a sergeant in the Fort Bext mercenary company. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.123'),
('templeton-c-badoon', 'Templeton C. Badoon', NULL, 'Trapper and bandit near Fort Brandt', 'palladium-fantasy', 'Human', 'Trapper / 3rd level Thief', 3, 'Anarchist', '50', NULL, NULL, '{"IQ":9,"ME":9,"MA":10,"PS":11,"PP":14,"PE":14,"PB":7,"Spd":12}', 33, NULL, NULL, NULL, NULL, 9, NULL, '{"attacks":2,"parry":2,"dodge":2}', 'First-edition figures, as printed. Attacks are 2 hand to hand or 4 with short bow. +2 to parry and dodge is plus W.P. bonuses. Tracking and trapping skills equal to a 5th level ranger. A.R. 9 is his soft leather/animal skins (S.D.C. 20). The scenario text says he looks about 60; the block prints age 50.', '[{"name":"Prowl","pct":67},{"name":"Pick Pockets","pct":52},{"name":"Identify Tracks","pct":64},{"name":"Track","pct":70},{"name":"Trap/skin small animals","pct":72},{"name":"Trap large animals","pct":58},{"name":"Speaks Southern and Eastern","pct":100},{"name":"Speaks Goblin and Dwarven","pct":85}]', 'Printed as pairs: Identify tracks 64/47%, Track 70/31%, Trap/skin small animals 72/76%.', NULL, NULL, NULL, NULL, NULL, 'Soft leather/animal skins (A.R. 9, S.D.C. 20); short bow, 24 arrows, 3 daggers, small axe. Also eight small animal snares, two metal traps (fox), 1/2 gal. of wine, water skin, 50ft of cord, hand made cloth, chewing tobacco.', '60 gold.', 'Noisy, coarse and thoroughly likeable, a merry swindler who drinks hard but will not gamble.', 'Three fellow thieves; has a standing arrangement with the commander of Fort Brandt', NULL, 'A grubby retired trapper in the optional scenario at Fort Brandt who offers to guide travellers to a cheaper ferry and instead walks them into a clearing of pits to be robbed, not killed. Gives up without a fight if cornered. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.124'),
('capt-torry-aberdaal', 'Capt. Torry Aberdaal', NULL, 'Captain of Fort Clay', 'palladium-fantasy', 'Human', '6th level Soldier', 6, 'Scrupulous', '29', NULL, NULL, '{"IQ":11,"PS":16,"PE":15,"PB":11}', 31, NULL, NULL, NULL, NULL, 15, NULL, '{"damage":1}', 'First-edition figures, as printed. +1 to damage is printed beside his P.S. A.R. 15 is his scale mail (S.D.C. 75). Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Scale mail (A.R. 15, S.D.C. 75).', NULL, 'Agreeable, outgoing, cheeky and far too sure of himself.', NULL, NULL, 'The young nobleman commanding Fort Clay, whose wealthy father arranged the posting and whose only fighting has been small border clashes. In the Ogre Invasion he refuses to believe his fort is in danger. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.125'),
('luisius-tandar', 'Luisius Tandar', NULL, 'Commander of Fort Garr', 'palladium-fantasy', 'Human', '7th level Soldier (light cavalry)', 7, 'Diabolic', '44', NULL, NULL, '{"IQ":10,"PS":24,"PE":13}', 32, NULL, NULL, NULL, NULL, 15, NULL, '{"damage":9}', 'First-edition figures, as printed. +9 to damage is printed beside his P.S. A.R. 15 is his chain and plate armour (S.D.C. 100). Other attributes are average (not printed).', '[{"name":"Scale Walls","pct":74},{"name":"Track","pct":62},{"name":"Identify Tracks","pct":56},{"name":"Speaks Southern, Eastern","pct":100},{"name":"Speaks Goblin","pct":98}]', 'Printed as pairs: Track 62/16%, Identify tracks 56/37%. Prowl is listed with no percentage of its own.', NULL, NULL, NULL, NULL, NULL, 'Chain and plate armour (A.R. 15, S.D.C. 100).', NULL, 'Crooked and out for himself, indifferent to whether his soldiers or anybody else live, while putting on a persuasive show of concern.', NULL, NULL, 'Officer in charge of Fort Garr, the ancient coastal fort and lighthouse with a garrison of 300 on the western border. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.125'),
('sir-brenn-marteek', 'Sir Brenn Marteek', NULL, 'Captain of the Sentinels, Fort Garr', 'palladium-fantasy', 'Elf', '5th level Knight, 2nd level Wizard', 5, 'Scrupulous', '40', NULL, NULL, '{"IQ":10,"PS":15,"PP":12,"PE":15,"PB":18}', 36, NULL, NULL, NULL, NULL, 15, NULL, NULL, 'First-edition figures, as printed. A.R. 15 is his scale mail (S.D.C. 75). Other attributes are average (not printed).', '[{"name":"Read/write Elven","pct":100},{"name":"Read/write Dwarven","pct":56},{"name":"Speaks Elven, Dwarven","pct":100},{"name":"Speaks Southern, Eastern, Goblin","pct":80}]', 'W.P. Lance, W.P. Large sword, W.P. Large shield.', NULL, '2nd level Wizard, can cast 3 spells daily: Decipher Magic, Sense Magic, Cloud of Slumber, Globe of Daylight, Tongues, Charm, Charismatic Aura, Sense Evil, Invisibility.', NULL, NULL, NULL, 'Scale mail (A.R. 15, S.D.C. 75).', NULL, 'A boastful, swaggering teller of tall tales, cheery if tiresome, yet upright and apparently incorruptible.', NULL, NULL, 'Elven knight and minor wizard who leads the 96 Sentinel cavalry at Fort Garr and has won their loyalty by always standing by them. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.125-126'),
('captain-josh-tankan', 'Captain Josh Tankan', NULL, 'Captain of Fort Hilde', 'palladium-fantasy', 'Human', '4th level Knight (cavalry), Major Psionic', 4, 'Scrupulous', '32', NULL, NULL, '{"IQ":10,"ME":8,"MA":10,"PS":14,"PP":15,"PE":12,"PB":9,"Spd":6}', 33, NULL, NULL, NULL, 28, 15, NULL, '{"attacks":2,"damage":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. Attacks are 2 hand to hand and 2 psionic. A.R. 15 is his plate and chain armour (S.D.C. 100).', NULL, NULL, NULL, NULL, 'Major Psionic, 28 I.S.P.: has all first level abilities, bio-regen, death trance, mind block, night vision, extended telepathy, see the invisible, evil eye: despair, stun, sleep, fear, and blind.', NULL, NULL, 'Plate and chain armour (A.R. 15, S.D.C. 100); awl pike, falchion, bastard sword, 2 knives, small shield. Misc. items, knives, riding gear. His horse Titan, a good riding horse worth about 3000 gold: Hit Points 31, max. spd. 50mph, leather and chain barding (A.R. 14, S.D.C. 60).', '240 gold.', 'Even-handed, sturdy, self-assured and forceful; his soldiers like him.', NULL, NULL, 'Psionic cavalry knight in command of Fort Hilde, the moated stone fort deep in the Old Kingdom that is mankind''s furthest outpost there. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.126'),
('captain-elliot-barodo', 'Captain Elliot Barodo', NULL, 'Captain of Fort Ibi', 'palladium-fantasy', 'Human', '6th level Mercenary Fighter', 6, 'Scrupulous', '36', NULL, NULL, '{"IQ":11,"PS":12,"PP":12}', 32, NULL, NULL, NULL, NULL, 16, NULL, NULL, 'First-edition figures, as printed. A.R. 16 is his battered splint armour (S.D.C. 82). Other attributes are average (not printed).', '[{"name":"Speaks Southern","pct":100},{"name":"Speaks Elf, Goblin, Western","pct":80}]', NULL, NULL, NULL, NULL, NULL, NULL, 'Splint armour, battered (A.R. 16, S.D.C. 82).', NULL, 'A gloomy man who is too fond of the bottle.', NULL, NULL, 'A big, heavyset mercenary who commands the 134 mixed-race mercenaries of Fort Ibi and its walled fort town. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.126'),
('captain-grint-pantlok', 'Captain Grint Pantlok', NULL, 'Captain of Fort Ibera', 'palladium-fantasy', 'Human', '5th level Soldier of noble birth', 5, 'Unprincipled', '29', NULL, NULL, '{"IQ":9,"PS":15,"PB":14}', 28, NULL, NULL, NULL, NULL, 17, NULL, '{"attacks":3,"damage":2,"parry":3,"dodge":3}', 'First-edition figures, as printed. W.P. bonuses not included. A.R. 17 is his plate armour (S.D.C. 120). Other attributes are average (not printed).', '[{"name":"Speaks Southern","pct":100},{"name":"Speaks Eastern, Western and Elven","pct":70},{"name":"Read/write Southern","pct":44}]', 'Horsemanship (general), W.P. Blunt, W.P. Spear, W.P. Short Sword.', NULL, NULL, NULL, NULL, NULL, 'Plate armour (A.R. 17, S.D.C. 120); spear, sabre, morning star, knife. Also riding gear, bastard sword, fine wine, clothes, etc.', '600 gold.', 'Upright, dependable, eager to rise, polite and schooled in manners.', NULL, NULL, 'Noble-born officer of the underground Fort Ibera with two years of border patrol behind him; the Fort Bext mercenaries have nicknamed him the soldier prince. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.127'),
('sir-lintalt-grimheart', 'Sir Lintalt Grimheart', 'Lintalt Whitesalt', 'Commander of Fort Indo, Knight of the Realm', 'palladium-fantasy', 'Elf', '15th level Scholar, 10th level Wizard, 6th level Summoner', 15, 'Unprincipled', '800', NULL, NULL, '{"IQ":14,"MA":12,"PS":8,"PP":15,"PB":23}', 153, NULL, NULL, NULL, NULL, 14, NULL, '{"attacks":2}', 'First-edition figures, as printed. Attacks are 2 hand to hand or 2 spells. +3 spell strength, +2 save vs. spell magic, +1 save vs. circles/symbols, plus various W.P. bonuses. A.R. 14 is his Cloak of armour (S.D.C. 212). Knight is an honorary title, not a class. Other attributes are average (not printed).', '[{"name":"Read/write Elven, Southern, Western, Eastern, Dwarven","pct":100}]', 'W.P. Staves, W.P. Short sword, W.P. Knives. Speaks all languages.', NULL, '10th level Wizard (also 6th level Summoner), 15 spells daily: Decipher Magic, Sense Magic, Cloud of Slumber, Tongues, Water to Wine, Ventriloquism, Spirit of the Wolf, Carpet of Adhesion, Mesmerism, Sense Traps, Mask of Deceit, Fleet Feet, Call Lightning, Fire Ball, Control the Beasts, Size of the Behemoth, Blind, Heal Self, Wall of Stone, Dispel Magic Barrier, Doppleganger, Stone to Flesh, Resurrection, and the Crimson Wall of Lictalon (a spell of legend).', NULL, NULL, NULL, 'Cloak of armour (A.R. 14, S.D.C. 212); bo staff, scimitar, knives. Various magic potions, powders and scrolls (2-8) hidden in the fort.', '10,000 to 40,000 gold hidden in the fort.', 'Sage, forbearing and sympathetic, but guarded enough that not even his family is told his real name or his secrets.', 'His six sons and three daughters; the 300 cavalry of Fort Indo', NULL, 'An 800-year-old elf, still young to look at, who commands Fort Indo, largest of the forts, near Old Timiro. Legend credits him with saving Old Timiro and King Jephon the First almost 600 years ago, for which he was made a Knight of the Realm. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.127-128'),
('sir-samuel-ibi', 'Sir Samuel Ibi', NULL, 'The Old Man, Commander of Fort Isib', 'palladium-fantasy', 'Human', '9th level Knight', 9, 'Unprincipled', '62', NULL, NULL, '{"IQ":8,"PS":12,"PP":12,"PE":13}', 47, NULL, NULL, NULL, NULL, 17, NULL, NULL, 'First-edition figures, as printed. A.R. 17 is his plate armour (S.D.C. 160). Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Plate armour (A.R. 17, S.D.C. 160).', NULL, 'Unhurried and relaxed, he gives nearly everybody the benefit of the doubt until they show they do not deserve it.', NULL, NULL, 'The ageing knight, with a visible limp, in charge of Fort Isib, a new wooden fort on a hilltop along the eastern border. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.128'),
('gilbert-green-the-dragon', 'The Dragon', 'Gilbert Green', 'Captain of Fort Kafi', 'palladium-fantasy', 'Human', '4th level Soldier, 3rd level Wizard', 4, 'Unprincipled', '39', NULL, NULL, '{"IQ":14,"PS":13,"PE":13,"Spd":11}', 51, NULL, NULL, NULL, NULL, 15, NULL, NULL, 'First-edition figures, as printed. A.R. 15 is his scale mail (S.D.C. 75). Other attributes are average (not printed).', '[{"name":"Speaks Southern and Dwarven","pct":100}]', 'W.P. Large sword, W.P. Pole arm, W.P. Knives, Horsemanship (general).', NULL, '3rd level Wizard, 5 spells daily: Decipher Magic, Sense Magic, Globe of Daylight, Tongues, Cloud of Slumber, Ventriloquism, Dust Storm, Magic Net, Magic Pigeon, and See the Invisible.', NULL, NULL, NULL, 'Scale mail (A.R. 15, S.D.C. 75).', NULL, 'Fatherly and domineering, he smothers his troops with protection. Hates dwarves.', NULL, NULL, 'Soldier and wizard in command of the 96 troops at Fort Kafi, an old dwarven underground fort beneath a rock hill and lookout tower. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.128'),
('captain-thomas-yri', 'Captain Thomas Yri', NULL, 'Captain of Fort Mirr', 'palladium-fantasy', 'Human', '7th level Ranger', 7, 'Anarchist', '40', NULL, NULL, NULL, 55, NULL, NULL, NULL, NULL, 12, NULL, NULL, 'First-edition figures, as printed. A.R. 12 is his studded leather armour (S.D.C. 38). No attributes printed.', '[{"name":"Tracking","pct":80},{"name":"Identify Tracks","pct":78},{"name":"Identify Plants/Fruit","pct":76},{"name":"Speaks Elven, Goblin, Southern and Eastern","pct":100}]', 'Printed as pairs: Tracking 80/34%, Identify tracks 78/57%, Identify plants/fruit 76/78%. Horsemanship (general), W.P. Long bow, W.P. Battle axe.', NULL, NULL, NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38).', NULL, 'Amiable and chatty on the surface, self-seeking and scheming beneath.', NULL, NULL, 'Ranger commanding the 150 regular army soldiers of Fort Mirr, which watches the mountain trails and the Mirr forest. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.128'),
('captain-fredrick-milton', 'Captain Fredrick Milton', NULL, 'Captain of Fort Pont', 'palladium-fantasy', 'Human', '8th level Soldier', 8, 'Anarchist', '52', NULL, NULL, '{"IQ":10,"PS":15,"Spd":12}', 43, NULL, NULL, NULL, NULL, 16, NULL, NULL, 'First-edition figures, as printed. A.R. 16 is his splint armour (S.D.C. 82). Other attributes are average (not printed).', '[{"name":"Pick Pockets","pct":50},{"name":"Scale Walls","pct":80},{"name":"Speaks Southern, Elven, Goblin","pct":100},{"name":"Speaks Western and Eastern","pct":78}]', 'Horsemanship (general), W.P. Spear, W.P. Large sword, W.P. Pole arms, W.P. Small shield. Can''t read or write.', NULL, NULL, NULL, NULL, NULL, 'Splint armour (A.R. 16, S.D.C. 82).', NULL, 'A rough old campaigner with a kind heart who loves turning raw recruits into decent troops; everyone is fond of him.', NULL, NULL, 'Veteran commander of the 72 soldiers at Fort Pont, the underground fort that backs up Fort Aberla on the road to central Timiro. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.129'),
('captain-randhall-carpenter', 'Captain Randhall Carpenter', NULL, 'Captain of Fort Saka', 'palladium-fantasy', 'Human', '5th level Ranger', 5, 'Unprincipled', '30', NULL, NULL, '{"IQ":16,"PS":13,"PE":13}', 32, NULL, NULL, NULL, NULL, 13, NULL, NULL, 'First-edition figures, as printed. A.R. 13 is his chain mail (S.D.C. 44). Other attributes are average (not printed).', '[{"name":"Identify Tracks","pct":64},{"name":"Track","pct":68},{"name":"Speaks Eastern, Goblin","pct":100},{"name":"Speaks Ogre, Elven","pct":85}]', 'Printed as pairs: Identify tracks 64/27%, Track 68/29%. W.P. Longbow.', NULL, NULL, NULL, NULL, NULL, 'Chain mail (A.R. 13, S.D.C. 44).', NULL, 'Bashful, quiet and lacking confidence, though a first-rate commander with a gift for organisation.', 'Lt. Brok the Butcher, Sgt. Petre Grinbo, the Dark-man and the 96 mercenaries of Fort Saka', NULL, 'Young ranger in charge of the brawling mercenary garrison at Fort Saka, a run-down wooden post protecting Sino on the northern border. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.129'),
('lt-brok-the-butcher', 'Lt. Brok the Butcher', 'Brok Tindel', 'Lieutenant of Fort Saka', 'palladium-fantasy', 'Ogre', '4th level Merc.', 4, 'Miscreant', '25', NULL, NULL, '{"IQ":11,"PS":17,"PE":19}', 38, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. No armour printed. Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Short-fused and touchy, a sore loser who trades in information and cheats travellers and gamblers alike, yet stays true to captain and crown.', NULL, 'Sgt. Petre Grinbo dislikes him', 'An ogre mercenary officer at Fort Saka. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.129'),
('sgt-petre-grinbo', 'Sgt. Petre Grinbo', NULL, 'Sergeant of Fort Saka', 'palladium-fantasy', 'Wolfen', '3rd level Ranger', 3, 'Scrupulous', '20', NULL, NULL, '{"IQ":9,"PS":23,"PE":19,"Spd":9}', 28, NULL, NULL, NULL, NULL, NULL, NULL, '{"damage":8}', 'First-edition figures, as printed. +8 to damage is printed beside his P.S. No armour printed. Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Easygoing and fond of conversation; has no liking for Brok.', NULL, NULL, 'A wolfen ranger who ended up a sergeant at Fort Saka after an adventure left him stuck a long way from his homeland. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.129'),
('the-dark-man-fort-saka', 'The Dark-man', NULL, 'Wizard of Fort Saka', 'palladium-fantasy', 'Changeling', '5th level Wizard', 5, 'Anarchist', '40', NULL, NULL, '{"IQ":13,"PP":12,"PE":11,"Spd":7}', 31, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. No armour or spell list printed. Other attributes are average (not printed).', NULL, NULL, NULL, '5th level Wizard; spells not listed.', NULL, NULL, NULL, NULL, NULL, 'Self-centred, brash and proud, hungry for wealth and influence.', NULL, NULL, 'A changeling who passes as an elf among the Fort Saka mercenaries; gossip has it he is lying low from an enemy on his trail. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.129'),
('sir-bartholemul-lington', 'Sir Bartholemul Lington', NULL, 'Commander of Fort Seb', 'palladium-fantasy', 'Human', '5th level Knight', 5, 'Unprincipled', '49', NULL, NULL, '{"IQ":8,"PS":14,"PE":11,"PB":8}', 31, NULL, NULL, NULL, NULL, 17, NULL, '{"attacks":3}', 'First-edition figures, as printed. A.R. 17 is his plate armour (S.D.C. 150). Other attributes are average (not printed).', '[{"name":"Read/write Southern","pct":64},{"name":"Speaks Southern","pct":100},{"name":"Speaks Elven, Goblin, Eastern","pct":90}]', 'Horsemanship (knight).', NULL, NULL, NULL, NULL, NULL, 'Plate armour (A.R. 17, S.D.C. 150); lance, mace and chain, battle axe. War horse named Mad-Cap, 5 years old (approx. value 15,000): Hit Points 50, Spd. 20mph, barding A.R. 14, S.D.C. 70.', NULL, 'Coarse, cross and quick to take offence, though honest and even-handed; aches to be accepted as a genuine nobleman and has no time for the rich or the haughty.', NULL, NULL, 'Sir Bart, a knight of poor family and doubtful pedigree stuck commanding the 96 mercenaries of shabby Fort Seb beside the dwarven mining city of Acorac. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.129-130');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('sir-lan-erath', 'Sir Lan Erath', NULL, 'Commander of Fort Tanda', 'palladium-fantasy', 'Dwarf', '6th level Knight, 4th level Mind Mage', 6, 'Anarchist', '50', NULL, NULL, '{"IQ":24,"ME":13,"MA":6,"PS":18,"PP":11,"PE":14,"PB":3,"Spd":6}', 53, NULL, NULL, NULL, 63, 17, NULL, '{"damage":3}', 'First-edition figures, as printed. +3 to damage is printed beside his P.S. I.Q. bonus adds 10% to all skills. A.R. 17 is his plate armour (S.D.C. 160). His block heading prints the fort''s name as Fort Tanada.', NULL, NULL, NULL, NULL, '4th level Mind Mage, I.S.P. 63: all Psi-abilities levels 1-4.', NULL, NULL, 'Plate armour (A.R. 17, S.D.C. 160).', NULL, 'A brilliant tactician with a short temper and a sour mood, who is even-handed with every soldier and, if anything, demands more of his fellow dwarves.', 'The elite squad of dwarven warriors (3rd to 5th level soldiers) who answer only to him', NULL, 'Dwarven knight and mind mage commanding the 300 light cavalry of Fort Tanda, which keeps order over the orc and goblin slaves working the land. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.130'),
('sir-bo-tinkerton', 'Sir Bo Tinkerton', NULL, 'Commander of Fort Tirr', 'palladium-fantasy', 'Human', '6th level Palladin', 6, 'Scrupulous', '35', NULL, NULL, '{"IQ":10,"PS":12,"PP":14,"PE":12}', 38, NULL, NULL, NULL, NULL, 17, NULL, NULL, 'First-edition figures, as printed. A.R. 17 is his golden plate armour (S.D.C. 160). Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Golden plate armour (A.R. 17, S.D.C. 160).', NULL, 'A reserved loner with a talent for administration, tactics and numbers, and such a dread of cats that none may enter the fort.', NULL, 'Sir Benedict the Lion resents him', 'Officer in charge of Fort Tirr, headquarters of the Timiro Royal Border Patrol. Mostly popular, though the Sentinels think him unfit and would rather serve under their own captain. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.130'),
('sir-benedict-the-lion', 'Sir Benedict the Lion', 'Benedict Aria the III', 'Captain of the Elite Sentinels, Fort Tirr', 'palladium-fantasy', 'Human', '10th level Knight', 10, 'Anarchist', '48', NULL, NULL, '{"IQ":16,"PS":14,"PP":18,"PB":12}', 59, NULL, NULL, NULL, NULL, 16, NULL, NULL, 'First-edition figures, as printed. A.R. 16 is his splint armour (S.D.C. 82). Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Splint armour (A.R. 16, S.D.C. 82).', NULL, 'A veteran who shows no mercy in a fight, swaggering and openly contemptuous of others, with the skill and brains to back it up; true to his Sentinels and the crown.', NULL, 'Resents Sir Bo Tinkerton for holding the command he wants', 'Leader of the 96 noble Sentinel cavalry based at Fort Tirr, who would like to see him replace the fort''s commander. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.130'),
('the-sphinx-rahl-pattu', 'The Sphinx', 'Rahl Pattu', 'Sphinx of the Adventure of the Mystic Parcels', 'palladium-fantasy', 'Sphinx', '6th level Wizard', 6, 'Anarchist', NULL, NULL, NULL, NULL, 61, NULL, NULL, NULL, NULL, 10, NULL, '{"attacks":2,"damage":6,"strike":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. A.R. 10 is natural. Attacks are 2 hand to hand (2-12 damage) or 2 magic. +2 on all saving throws, +4 save vs. spell magic. +2 spell strength (victims need to roll 14 or higher to save). Size is printed only as Very Large. No attributes printed.', '[{"name":"Faerie Lore","pct":75},{"name":"Demon and Devil Lore","pct":75},{"name":"Racial History","pct":68},{"name":"Religious Doctrine","pct":73},{"name":"Imitate Voices","pct":56},{"name":"Speaks all languages","pct":95}]', NULL, 'Those of a sphinx; the entry only refers the reader to the first Palladium RPG book for them.', '6th level Wizard, +2 spell strength, two spell attacks per melee, can cast nine spells daily. Spells known: Charm, decipher, blinding flash, cloud of smoke, cloud of slumber, invisibility, levitate, tongues, fog of fear, call lightning, fireball, negate magic, heal self, heal burns, metamorphosis (self), and magic pigeon.', NULL, NULL, NULL, NULL, NULL, 'Shrewd, haughty and self-serving rather than outright evil. He bullies and manipulates, always gives warning before he strikes, and withdraws to take revenge later sooner than fight to the death. Elves he distrusts; other humanoids he holds cheap.', NULL, 'Whoever holds the magic medallion he took from a priest of Thoth he killed', 'The pursuer in the Adventure of the Mystic Parcels (set at Fort Brandt and the road to Arian), who overtakes late couriers around the fifth or sixth day to demand the medallion hidden in the warded parcel. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.133'),
('fire-brand-the-giant', 'Fire Brand', 'Tyr', 'Self-proclaimed Lord, leader of the Raiders (The Giant Firebrand and his Raiders)', 'palladium-fantasy', 'Nimro (fire) giant', '5th level Mercenary Fighter', 5, 'Diabolic', NULL, NULL, NULL, '{"IQ":8,"ME":11,"MA":14,"PS":19,"PP":19,"PE":25,"PB":11,"Spd":8}', 48, NULL, NULL, NULL, NULL, 9, NULL, '{"attacks":3,"damage":6,"strike":2,"parry":4,"dodge":4}', 'First-edition figures, as printed. 3 hand to hand attacks plus one fire breath attack per melee. +6 to damage is with O.C.C. combat bonus. +5 vs. magic and poison, impervious to fire. A.R. 9 is his bronze 1/2 plate (S.D.C. 30). The scenario text spells his kind Nimiro giant; his block spells it Nimro.', '[{"name":"Speaks Giant/Troll","pct":100},{"name":"Speaks Goblin, Orc and Southern","pct":80}]', 'W.P. Short Sword, W.P. Large Sword, W.P. Pole Arm.', NULL, 'None.', NULL, NULL, NULL, 'Bronze 1/2 plate (A.R. 9, S.D.C. 30); giant size beaked axe, scimitar, bull whip, dagger. Wears a large emerald ring (2000 gold), bronze arm and wrist bands (200 gold total), bronze chest plate (400 gold, 60lbs), bronze helmet (70 gold). Various clothing, one potion of invisibility and one wizard scroll of heal self (2-12 hit points), which he cannot use but guards.', NULL, 'Violent and belligerent, he revels in fighting and never turns down single combat, though he cheats to win. A bully who enjoys cruelty so long as none of it lands on him.', 'Melbrik, the goblin rangers Mik and Gark, and thirteen raiders', NULL, 'A fire giant out of the Old Kingdom who has seized a stretch of the north-eastern Timiro forests roughly 70 miles across and terrorises its poor settlers, threatening massacre if soldiers are called. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.135'),
('melbrik', 'Melbrik', NULL, 'Sgt. at Arms, second in command of Fire Brand''s Raiders', 'palladium-fantasy', 'Orc', '3rd level Mercenary Fighter', 3, 'Miscreant', NULL, NULL, NULL, '{"IQ":10,"PS":20}', 29, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":2,"damage":6,"parry":2,"dodge":2}', 'First-edition figures, as printed. +6 to damage includes O.C.C. bonus. A.R. 12 is his studded leather armour (S.D.C. 33). Other attributes are average (not printed).', '[{"name":"Medical","pct":44},{"name":"Speaks Goblin/Orc","pct":100},{"name":"Speaks Troll/Giant and Eastern","pct":60}]', 'Medical is printed 44%/48%. W.P. Battle Axe, W.P. Large Sword, W.P. Knife, Horsemanship (general).', NULL, NULL, NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 33); battle axe, broad sword, two knives. Also a pint of good wine, 100 ft. of rope, ragged clothing.', '42 silver pieces, 56 gold pieces.', 'Sharp-witted and observant, sure of himself and hard as nails.', 'Fire Brand and his raiders', NULL, 'The orc who serves as the giant Fire Brand''s deputy in the raider band preying on north-eastern Timiro. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.135'),
('mik-the-goblin-ranger', 'Mik', NULL, 'Goblin ranger of Fire Brand''s Raiders', 'palladium-fantasy', 'Goblin', '3rd level Ranger', 3, 'Diabolic', NULL, NULL, NULL, '{"IQ":9,"PS":10,"PE":14}', 27, NULL, NULL, NULL, NULL, 9, NULL, '{"attacks":2,"damage":2,"strike":1,"parry":1,"dodge":1}', 'First-edition figures, as printed. A.R. 9 is his soft leather armour (S.D.C. 20). Other attributes are average (not printed).', '[{"name":"Track","pct":56},{"name":"Identify Tracks","pct":52},{"name":"Trap/Skin Small Animals","pct":56},{"name":"Prowl","pct":34},{"name":"Speaks Goblin","pct":100},{"name":"Speaks Eastern, Southern and Elven","pct":65}]', 'Printed as pairs: Track 56/15%, Identify Tracks 52/37%, Trap/Skin Small Animals 56/60%. W.P. Short Bow, W.P. Knives.', NULL, NULL, NULL, NULL, NULL, 'Soft leather armour (A.R. 9, S.D.C. 20); short bow (23 arrows), short sword, 3 daggers. Also 3 small animal snares, 2 lbs. jerked beef.', '4 gold coins, 12 silver (lost most of his money gambling).', 'Sour and quarrelsome, a compulsive gambler who is vicious and holds grudges.', 'His brother Gark; Fire Brand', NULL, 'One of two goblin brothers scouting for the giant Fire Brand, whose treachery has undone several local champions. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.135'),
('gark-the-goblin-ranger', 'Gark', NULL, 'Goblin ranger of Fire Brand''s Raiders', 'palladium-fantasy', 'Goblin', '3rd level Ranger', 3, 'Anarchist', NULL, NULL, NULL, '{"IQ":10,"PS":11,"PP":19,"PE":13}', 26, NULL, NULL, NULL, NULL, 9, NULL, '{"attacks":2,"strike":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. +3 to strike, parry and dodge includes O.C.C. bonus. A.R. 9 is his soft leather armour (S.D.C. 20). Other attributes are average (not printed).', '[{"name":"Track","pct":56},{"name":"Identify Tracks","pct":52},{"name":"Identify Plants","pct":44},{"name":"Prowl","pct":34}]', 'Printed as pairs: Track 56/15%, Identify Tracks 52/37%, Identify Plants 44/46%. W.P. Blunt, W.P. Throwing Axe, W.P. Knives. Speaks the same languages as Mik (Goblin 100%, Eastern, Southern and Elven 65%).', NULL, NULL, NULL, NULL, NULL, 'Soft leather armour (A.R. 9, S.D.C. 20); morning star, short sword, throwing axe, 3 knives. Also 2 small animal snares, 1 lb. jerked beef, pint of poor rum.', '67 gold coins, 21 silver.', 'Relaxed in manner but sly, and fights dirty.', 'His brother Mik; Fire Brand', NULL, 'The luckier gambler of the two goblin brothers who scout for the giant Fire Brand and his raiders. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.135'),
('pohl-andee', 'Pohl Andee', NULL, 'Group leader of the changelings, Ogre Invasion', 'palladium-fantasy', 'Changeling', '6th level Thief', 6, 'Diabolic', '23', NULL, NULL, '{"IQ":10,"ME":22,"MA":18,"PP":14,"PE":6}', 29, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3}', 'First-edition figures, as printed. 3 attacks per melee is printed among his skills. A.R. 12 is his studded leather armour (S.D.C. 38). Other attributes are average (not printed).', '[{"name":"Prowl","pct":63},{"name":"Scale Walls","pct":66},{"name":"Pick Pocket","pct":57},{"name":"Locate Secret Doors","pct":42},{"name":"Speaks Ogre, Elven, Orc","pct":100},{"name":"Speaks Southern","pct":90}]', 'W.P. Knives, W.P. Blunt.', NULL, NULL, NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38); black jack. Scroll (written in elven) cloud of smoke, one potion of healing (restores 2-12 hit points), pipe and smoking tobacco, clothes, riding gear, a sapphire (worth 2000 gold), a ruby ring (worth 1800 gold).', 'An Old Kingdom 500 gold piece coin.', 'A vengeful plotter who delights in torture and killing, pitiless in a fight and a forceful leader.', 'Fourteen other changelings; answers only to Master Slayer and The Shadow', NULL, 'Head of the fifteen shape-changing infiltrators who slip into forts ahead of the ogre army in the Ogre Invasion, seeking revenge on humankind. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.138'),
('master-slayer', 'Master Slayer', 'Butte Crii', 'Ogre leader of the Ogre Invasion, Ogre Pass', 'palladium-fantasy', 'Ogre', '5th level Mercenary Fighter', 5, 'Miscreant', '24', NULL, NULL, '{"IQ":10,"PS":27,"PP":20,"PE":18}', 37, NULL, NULL, NULL, NULL, 15, NULL, '{"attacks":2,"damage":14,"strike":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. +14 to damage is with combat bonuses. +2 save vs. magic and poison. W.P. skill bonuses not included. A.R. 15 is his splint armour (S.D.C. 75), as printed. Other attributes are average (not printed).', '[{"name":"Prowl","pct":47},{"name":"Identify Tracks","pct":47},{"name":"Track","pct":48},{"name":"Scale Walls","pct":60},{"name":"Speaks Ogre, Goblin, Southern","pct":100},{"name":"Speaks Elven","pct":80}]', 'Printed as pairs: Identify tracks 47/30%, Track 48/9%. Horsemanship: general.', NULL, NULL, NULL, NULL, NULL, 'Splint armour (A.R. 15, S.D.C. 75); giant sized trident, short sword, hercules club, two daggers. Riding gear, clothes, extra dagger and trident, two healing potions (restore 1-8 hit points each), jade ring (approx. value 300 gold), simple gold band ring (magic: turn invisible 3X daily, equal to a 6th level spell), gallon of wine, two emeralds (approx. value 2000 gold each). A 2 year old horse, Kea-la, approx. value 20,000 gold, Spd. 20mph, Hit Points 57, leather barding (A.R. 10, S.D.C. 40).', '1300 in gold coins, kept in his personal wagon/tent.', 'Proud and contemptuous of others, a wily tactician who spends his followers'' lives freely; every warrior is afraid of him.', 'The Shadow, Cyclone, Brother Wind, his brother Spear, the changelings under Pohl Andee, Father Tarka of Baca (by secret pact); two loyal orc guards at his wagon/tent', NULL, 'Chief of the best organised ogre tribe at the Ogre Pass and mastermind of the Ogre Invasion, the march on Fort Calda, Fort Clay and the town of Erat. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.138'),
('the-shadow-ril-labot', 'The Shadow', 'Ril Labot', 'Ogre leader of the Ogre Invasion', 'palladium-fantasy', 'Ogre (in appearance)', '2nd level Assassin, 3rd level Mind Mage', 3, 'Diabolic', '40', NULL, NULL, NULL, 26, NULL, NULL, NULL, 60, 12, NULL, '{"attacks":2}', 'First-edition figures, as printed. The block says he Appears to be an Ogre. 2 hand to hand attacks plus one psionic. +3 to save vs. psionics, 60% trust/intimidate. A.R. 12 is his studded leather armour (S.D.C. 38). No attributes printed.', NULL, NULL, NULL, NULL, '3rd level Mind Mage, 60 I.S.P.: can perform all psionics levels 1-3.', NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38); short bow, bo staff, broad sword, four knives.', NULL, NULL, 'Master Slayer, Cyclone, Brother Wind; Pohl Andee answers to him', NULL, 'Listed among the four ogre leaders of the Ogre Invasion, a psionic assassin whose block notes only that he looks like an ogre. No personality is printed. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.138-139'),
('cyclone-bu-tiib', 'Cyclone', 'Bu Tiib', 'Ogre leader of the Ogre Invasion', 'palladium-fantasy', 'Ogre', '6th level Air Warlock', 6, 'Diabolic', '30', NULL, NULL, '{"IQ":9,"ME":15,"PS":18,"PP":10,"PE":13,"Spd":12}', 36, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":1,"damage":3}', 'First-edition figures, as printed. 1 hand to hand attack, 2 spell attacks per melee. +1 save vs. magic, +1 spell strength. A.R. 12 is his studded leather armour (S.D.C. 38). Other attributes are average (not printed).', '[{"name":"Dowsing","pct":72},{"name":"Recognize Precious Stones/Metals","pct":55},{"name":"Speaks Ogre and Goblin","pct":100}]', 'W.P. Knives (throwing spikes), W.P. Blunt. Can''t read/write or ride a horse.', NULL, '6th level Air Warlock, 12 spells daily: Cloud of Slumber, Create Light, Wind Rush, Silence (15ft radius), Call Lightning, Resist Cold, Dissipate Gases, Invisibility, Breath of Life, Invisible Wall, Electric Field/Wall, Snow Storm. 30% chance to summon an elemental.', NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38); a dozen wood throwing spikes, wood war club. Another 24 wood spikes, 2 daggers, clothes, 2 gallons of rum, looted jewelry (approx. value 1200 gold).', '350 in gold coins.', 'Jittery and never still, savage and pitiless, with a permanently grim face.', 'Master Slayer, The Shadow, Brother Wind', NULL, 'The stronger of the two air warlocks among the ogre leaders of the Ogre Invasion; their lightning, cloud and snow storms open each night assault and cover the retreat. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.139'),
('brother-wind-rig-ko', 'Brother Wind', 'Rig-Ko', 'Ogre leader of the Ogre Invasion', 'palladium-fantasy', 'Ogre', '4th level Air Warlock', 4, 'Anarchist', '32', NULL, NULL, '{"IQ":12,"ME":12,"PS":19,"PP":9,"PE":14,"Spd":5}', 28, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":1,"damage":4}', 'First-edition figures, as printed. 1 hand to hand attack, 2 spell attacks per melee. +1 to save vs. magic, +1 spell strength. A.R. 12 is his studded leather armour (S.D.C. 38). Other attributes are average (not printed).', '[{"name":"Medical","pct":56},{"name":"Speaks Ogre, Goblin","pct":100},{"name":"Speaks Eastern and Elven","pct":60}]', 'Medical is printed 56/60%. W.P. Staves.', NULL, '4th level Air Warlock, 8 spells daily: Cloud of Steam, Breath Without Air, Mesmerism, Levitate, Call Lightning, Darkness, Calm Storm, Protection from lightning.', NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38); giant sized iron staff, 2 daggers. Personal effects, gallon of good wine, dried herbs and mushrooms.', '400 gold in coins.', 'Nasty, distrustful and quick to seek revenge.', 'Master Slayer, The Shadow, Cyclone', NULL, 'The lesser air warlock among the four ogre leaders of the Ogre Invasion. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.139'),
('spear-timbok-crii', 'Spear', 'Timbok Crii', 'Brother of Master Slayer, Ogre Invasion', 'palladium-fantasy', 'Ogre', '3rd level Assassin', 3, 'Miscreant', '18', NULL, NULL, '{"IQ":9,"PS":19,"PP":14,"PE":11,"Spd":15}', 26, NULL, NULL, NULL, NULL, 13, NULL, '{"attacks":2,"damage":6}', 'First-edition figures, as printed. +6 to damage is with hand to hand bonus. A.R. 13 is his chain mail (S.D.C. 44).', '[{"name":"Prowl","pct":50},{"name":"Scale Walls","pct":53},{"name":"Identify Tracks","pct":34},{"name":"Track","pct":41},{"name":"Use Poison","pct":39},{"name":"Recognize Poison","pct":35},{"name":"Speaks Ogre and Goblin","pct":100}]', 'Printed as pairs: Identify Tracks 34/19%, Track 41/10%. W.P. Pole arm, W.P. Spear, W.P. Short sword, W.P. Knives. Can''t read/write or ride a horse.', NULL, NULL, NULL, NULL, NULL, 'Chain mail (A.R. 13, S.D.C. 44); giant size awl pike, short spear, javelin, sword; 3 knives (normal size). Also 2 extra javelins, 3 extra knives, suit of soft leather armour, jewel studded chalice (10 gems worth 100 gold each, total 1000 gold).', '250 in gold coins.', 'Brash, unruly, too sure of himself and full of anger.', 'His brother Master Slayer', NULL, 'The eighteen-year-old younger brother of the ogre war leader Master Slayer, an assassin riding with the Ogre Invasion; he is not counted among the four leaders. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.139'),
('lin-the-elf', 'Lin', 'Lindeer Robolin', 'Northern traveler, the Adventure of the Hidden Temple', 'palladium-fantasy', 'Elf', '2nd level Wizard, 5th level Assassin', 5, 'Anarchist', 'Appears about 35 or 40 by human standards', NULL, NULL, '{"IQ":12,"ME":9,"MA":11,"PS":12,"PP":20,"PE":12,"PB":24,"Spd":10}', 39, NULL, NULL, NULL, NULL, 14, NULL, '{"attacks":3,"strike":3,"parry":3,"dodge":3,"damage":2}', 'First-edition figures, as printed. Attacks are 3 hand to hand or 1 magic. +1 on all saving throws; 70% likelihood to impress and charm (P.B. bonus). +4 to parry with his small iron shield. A.R. 14 is his magic (noiseless) chain and leather armour (S.D.C. 60). 61% likelihood of using the rune dagger when angry, seriously injured or in extreme danger; each time it is drawn there is a 31% chance of a death/berserker rage lasting 3-12 melees.', '[{"name":"Scale Walls","pct":65},{"name":"Prowl","pct":62},{"name":"Pick Pockets","pct":40},{"name":"Use Poison","pct":55},{"name":"Recognize Poison","pct":55},{"name":"Recognize Weapon Quality","pct":60},{"name":"Disguise","pct":48},{"name":"Swim","pct":80},{"name":"Speaks and Reads Elven","pct":100},{"name":"Speaks Southern, Wolfen and Goblin","pct":85},{"name":"Study Symbols and Circles (to recognize)","pct":45}]', 'Disguise is printed 48/18%. W.P. Knives, W.P. Pole Arms, W.P. Blunt, W.P. Small Shield.', NULL, '2nd level Wizard, can cast 3 spells daily (in addition to those of the rune dagger): Decipher Magic, Globe of Day Light, Tongues, Sense Magic, Cloud of Slumber, Fly, Chameleon and Carpet of Adhesion. Rune dagger spells at 6th level strength: Cloud of Smoke, Fire Ball, Firey Touch, and Circle of Flame.', NULL, NULL, NULL, 'Chain and leather armour (magic: noiseless; A.R. 14, S.D.C. 60); small iron shield, 2 knives, mace, glaive. The rune dagger Darkling: indestructable blue grey blade, I.Q. 11, alignment Diabolic, damage 4-24; abilities: Clerical, Healing touch (2-12), Remove curse 56% (does not apply to itself), turn the dead 55%, animate/command 2-12 dead 64%; cursed, it continually begs Lin to use it. Dark cape, quality leather gloves, boots, back pack, 3 small sacks, blank note book, chalk, pen and ink.', '1200 in northern gold (6 coins) in a pouch inscribed with mystic symbols; another 400 gold (four 100 gold pieces) in a secret pocket in the right pant leg.', 'Brooding and soft-spoken yet commanding and proud, he looks down on other races, confides in nobody and misses nothing; hard without being sadistic. Keeps his word unless betrayed first.', 'Grizzle-Bok the Wolfen', NULL, 'A nobly born elf with grey-streaked black hair, one of two survivors of a northern expedition wrecked by ogres. He hires the party to help recover an ancient book from a lost temple of Amon and will destroy anyone who keeps it from him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.142-143'),
('grizzle-bok', 'Grizzle-Bok', NULL, 'Northern traveler, the Adventure of the Hidden Temple', 'palladium-fantasy', 'Wolfen', '4th level Ranger', 4, 'Unprincipled', '24', 'Nearly nine feet', NULL, '{"IQ":14,"ME":10,"MA":8,"PS":17,"PP":13,"PE":13,"PB":11,"Spd":23}', 28, NULL, NULL, NULL, NULL, 13, NULL, '{"attacks":2,"damage":2,"strike":1,"parry":1,"dodge":1}', 'First-edition figures, as printed. Hand to hand and attribute bonuses are included. A.R. 13 is his chain mail (S.D.C. 42). Grizzle-Bok is noted as his true name. The temple key gives him a 62% chance to leap a 15ft pit.', '[{"name":"Identify Tracks","pct":54},{"name":"Track","pct":62},{"name":"Identify Plants/Fruits","pct":54},{"name":"Prowl","pct":40},{"name":"Trap/skin small animals","pct":64},{"name":"Speaks Wolfen and Eastern","pct":100},{"name":"Speaks Goblin and Southern","pct":75},{"name":"Recognize Poison","pct":40}]', 'Printed as pairs: Identify Tracks 54/56%, Track 62/27%, Identify Plants/fruits 54/56%, Trap/skin small animals 64/68%. W.P. Throwing Axe, W.P. Large Sword, W.P. Small Shield.', NULL, NULL, NULL, NULL, NULL, 'Chain mail (A.R. 13, S.D.C. 42); large throwing axe, large spear, broad sword, 3 knives, small iron shield (large by human standards). Back pack, 2 torches, bedroll, 8lbs of jerked beef, 100ft rope, 6 iron spikes, leather boots and gloves, chalk, and a prayer book to Hiem the Huntress and Algor the giant God (written in wolfen).', NULL, 'A soldier''s son, disciplined but stubborn, cheeky and sure of himself, soured against humans by the abuse he has met in the south. Faithful once his respect is earned; until then he sneers at blunders and may pilfer from companions.', 'Lin the elf', NULL, 'A towering wolfen ranger detached from the Imperial Army of the Wolfen for a special task, the other survivor of the northern party seeking the book in the Hidden Temple. He most likely heads home north once the adventure ends. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.143'),
('kra-hidden-temple', 'Kra', NULL, 'Goblin of the Goblins Lair, the Hidden Temple', 'palladium-fantasy', 'Goblin', NULL, NULL, 'Evil', NULL, NULL, NULL, NULL, 16, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":1,"strike":2,"parry":2,"dodge":2}', 'First-edition figures, as printed. Printed as +2 to str/p/d. No armour.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No armour; short sword.', 'The room holds 13 gold and 37 silver between its five goblins.', 'Hostile, but will not start a fight against a larger or stronger party.', NULL, NULL, 'One of two male goblins living in room 3 of the Hidden Temple, just past the pit trap. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.144'),
('tilu-hidden-temple', 'Tilu', NULL, 'Goblin of the Goblins Lair, the Hidden Temple', 'palladium-fantasy', 'Goblin', NULL, NULL, 'Evil', NULL, NULL, NULL, NULL, 14, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":1}', 'First-edition figures, as printed. No armour.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No armour; knife and club.', 'The room holds 13 gold and 37 silver between its five goblins.', 'Hostile, but will not start a fight against a larger or stronger party.', NULL, NULL, 'The second male goblin in room 3 of the Hidden Temple, sharing it with Kra and three females. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.144'),
('tra-hidden-temple', 'Tra', NULL, 'Goblin of the Goblins Lair, the Hidden Temple', 'palladium-fantasy', 'Goblin', NULL, NULL, 'Evil', NULL, NULL, NULL, NULL, 18, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":1,"strike":2,"parry":2,"dodge":2}', 'First-edition figures, as printed. One hand to hand attack or 2 attacks per melee with the short bow.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Short sword and short bow.', '20 gold', 'Hostile, but locks himself in rather than face a larger or stronger party.', NULL, NULL, 'One of four male goblins quartered in room 4 of the Hidden Temple. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.144'),
('grint-hidden-temple', 'Grint', NULL, 'Goblin of the Goblins Lair, the Hidden Temple', 'palladium-fantasy', 'Goblin', NULL, NULL, 'Evil', NULL, NULL, NULL, NULL, 16, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":1,"strike":1,"parry":1,"dodge":1}', 'First-edition figures, as printed. One hand to hand attack or 2 attacks per melee with the short bow.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Short sword and short bow (no damage printed for his).', '20 gold', 'Hostile, but locks himself in rather than face a larger or stronger party.', NULL, NULL, 'One of four male goblins quartered in room 4 of the Hidden Temple. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.144'),
('miil-hidden-temple', 'Miil', NULL, 'Goblin of the Goblins Lair, the Hidden Temple', 'palladium-fantasy', 'Goblin', NULL, NULL, 'Evil', NULL, NULL, NULL, NULL, 12, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":1,"strike":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. One hand to hand attack or 2 attacks per melee with the short bow.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Mace and short bow.', '20 gold', 'Hostile, but locks himself in rather than face a larger or stronger party.', NULL, NULL, 'One of four male goblins quartered in room 4 of the Hidden Temple. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.144'),
('larr-hidden-temple', 'Larr', NULL, 'Goblin of the Goblins Lair, the Hidden Temple', 'palladium-fantasy', 'Goblin', NULL, NULL, 'Evil', NULL, NULL, NULL, NULL, 15, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":1,"strike":2,"parry":2,"dodge":2}', 'First-edition figures, as printed. One hand to hand attack or 2 attacks per melee with the short bow.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Sabre and short bow (no damage printed for his).', '20 gold', 'Hostile, but locks himself in rather than face a larger or stronger party.', NULL, NULL, 'One of four male goblins quartered in room 4 of the Hidden Temple. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.144'),
('trreeberr', 'Trreeberr', NULL, 'Bogie guard of the Hidden Temple', 'palladium-fantasy', 'Bogie', NULL, NULL, 'Miscreant', NULL, NULL, NULL, NULL, 26, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Powers are not printed here; the book refers to the Palladium R.P.G. p.229.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cruel and vengeful; opens with spells, runs when losing and comes back later to pick victims off from behind.', 'Cahblee, the other bogie', NULL, 'One of two bogies summoned 300 years ago to guard the Hidden Temple, found posing as a spider above the second door of area 15, where the pair keep their hoard in rag mounds. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.145'),
('cahblee', 'Cahblee', NULL, 'Bogie guard of the Hidden Temple', 'palladium-fantasy', 'Bogie', NULL, NULL, 'Miscreant', NULL, NULL, NULL, NULL, 42, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Powers are not printed here; the book refers to the Palladium R.P.G. p.229.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cruel and vengeful; opens with spells, runs when losing and comes back later to pick victims off from behind.', 'Trreeberr, the other bogie', NULL, 'One of two bogies summoned 300 years ago to guard the Hidden Temple, found posing as a spider above the second door of area 15, where the pair keep their hoard in rag mounds. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.145'),
('gurgoyle-of-the-hidden-temple', 'Gurgoyle of the Hidden Temple', NULL, 'Gurgoyle lurking in room 19 of the Hidden Temple', 'palladium-fantasy', 'Gurgoyle', NULL, NULL, 'Diabolic', NULL, NULL, NULL, NULL, 55, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3}', 'First-edition figures, as printed. A.R. 12 is natural. Other abilities are not printed here; the book refers to sub-demons, Palladium R.P.G. p.173.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A spear, his only valuable (no damage printed).', NULL, 'Stands still among the statues and jumps a small party from the rear as its last member leaves.', NULL, NULL, 'A living gurgoyle standing as the third of three statues in room 19 of the Hidden Temple, itself a victim of the temple''s bogies. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.146'),
('spectre-of-the-hidden-temple', 'Spectre of the Hidden Temple', NULL, 'Spectre imprisoned in coffin H, room of bones, the Hidden Temple', 'palladium-fantasy', 'Spectre', NULL, NULL, 'Miscreant', NULL, NULL, NULL, NULL, 31, NULL, NULL, NULL, 90, 14, NULL, '{"attacks":2}', 'First-edition figures, as printed. A.R. 14 is natural. The 2 attacks are psionic. Further abilities are not printed here; the book refers to the Palladium R.P.G. p.232.', NULL, NULL, NULL, NULL, 'Has all psionic abilities level one through three. 90 I.S.P.', NULL, NULL, NULL, NULL, 'A liar who begs by telepathy to be let out and promises anything; even odds he kills whoever frees him.', NULL, NULL, 'A spectre held in a wax-sealed, chained and warded coffin in room 21 of the Hidden Temple. It owns nothing and knows of no treasure. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.146'),
('skeleton-thing', 'The Skeleton-Thing', NULL, 'Enthroned protector of the Temple of Amon, the Hidden Temple', 'palladium-fantasy', NULL, NULL, NULL, 'Anarchist', NULL, '16 ft tall', NULL, NULL, 170, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Regenerates 25 hit points every 20 hours. Immobile: only its head and mouth move, so it has no attacks of its own.', NULL, 'Speaks all languages', 'Magic of every kind, psionics, fire and cold do nothing to it; only physical blows hurt. It raises a new skeleton from loose bones once every four melees, can animate fallen party members, and commands the room''s skeletons and two golems, all of which drop when it is destroyed.', NULL, NULL, NULL, NULL, NULL, NULL, 'Waits for intruders to gather, then demands they leave every possession behind; one refusal dooms the whole group.', 'Nine skeletons (40 hit points each) and two damaged stone golems (19 and 33 hit points)', NULL, 'A huge, dried-out reptilian being from another world seated on a rune-covered throne in chamber 23 of the Hidden Temple, behind a circle of death. Whoever takes the throne after it becomes the next protector. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.148'),
('krilo', 'Krilo', NULL, 'Goblin priest and key-holder, northern corridor of the Hidden Temple', 'palladium-fantasy', 'Goblin', '3rd level thief', 3, NULL, NULL, NULL, NULL, '{"IQ":9,"PP":20,"PS":18}', 22, NULL, NULL, NULL, NULL, NULL, NULL, '{"strike":3,"parry":3,"dodge":3,"damage":3}', 'First-edition figures, as printed. Other attributes are average (not printed). The strike/parry/dodge bonus is from P.P., the damage bonus from P.S.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Dagger (no damage printed); grey robes; a pair of keys that open every door in the northern section.', NULL, 'Silent under questioning, even when tortured.', NULL, NULL, 'A goblin priest of the dark gods, Amon among them, who tends the northern section of the Hidden Temple; met in corridor N-4 or the kitchen N-6. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('gak-hidden-temple', 'Gak', NULL, 'Goblin of room N-11, the Hidden Temple', 'palladium-fantasy', 'Goblin', '2nd level thief', 2, 'Diabolic', NULL, NULL, NULL, NULL, 18, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Daggers and a short sword (no damage printed).', 'The four goblins of the room hold 33 gold in coins between them.', NULL, NULL, NULL, 'One of four goblins sharing room N-11 in the northern section of the Hidden Temple, part of Liber the Cobbler''s band. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('blint-hidden-temple', 'Blint', NULL, 'Goblin of room N-11, the Hidden Temple', 'palladium-fantasy', 'Goblin', '2nd level thief', 2, 'Diabolic', NULL, NULL, NULL, NULL, 22, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Daggers and a short sword (no damage printed).', 'The four goblins of the room hold 33 gold in coins between them.', NULL, NULL, NULL, 'One of four goblins sharing room N-11 in the northern section of the Hidden Temple, part of Liber the Cobbler''s band. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('credii-hidden-temple', 'Credii', NULL, 'Goblin of room N-11, the Hidden Temple', 'palladium-fantasy', 'Goblin', '1st level merc.', 1, 'Diabolic', NULL, NULL, NULL, NULL, 13, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Daggers and a short sword (no damage printed).', 'The four goblins of the room hold 33 gold in coins between them.', NULL, NULL, NULL, 'One of four goblins sharing room N-11 in the northern section of the Hidden Temple, part of Liber the Cobbler''s band. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('meltar-hidden-temple', 'Meltar', NULL, 'Goblin of room N-11, the Hidden Temple', 'palladium-fantasy', 'Goblin', '2nd level merc.', 2, 'Diabolic', NULL, NULL, NULL, NULL, 16, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Daggers and a short sword (no damage printed).', 'The four goblins of the room hold 33 gold in coins between them.', NULL, NULL, NULL, 'One of four goblins sharing room N-11 in the northern section of the Hidden Temple, part of Liber the Cobbler''s band. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('liber-the-cobbler', 'Liber, the Cobbler', NULL, 'Leader of the goblin band in the Hidden Temple', 'palladium-fantasy', 'Cobbler (goblin)', '4th level Thief', 4, 'Miscreant', NULL, NULL, NULL, '{"IQ":10,"PS":15,"PP":17,"Spd":3}', 32, NULL, NULL, NULL, NULL, 12, NULL, '{"strike":1,"parry":1,"dodge":1}', 'First-edition figures, as printed. Other attributes are average (not printed). The +1 to strike/parry/dodge is from P.P. A.R. 12 is his studded leather armour (S.D.C. 38).', NULL, NULL, 'Being a cobbler, he changes shape at will into a frog, toad, rat, mouse or weasel and knows a few spells; details are in the Palladium R.P.G. p.197, not here.', 'Casts a handful of spells (not listed; see the Palladium R.P.G. p.197).', NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38); magic battle axe that returns when thrown; two silver daggers; one potion of healing (2-12).', '88 gold', NULL, NULL, NULL, 'The cobbler who leads the goblins squatting in the old priests'' studies (N-9 to N-16) of the Hidden Temple, living in the better-furnished room N-12. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('grindle-nose', 'Grindle-nose', NULL, 'Priest of darkness/Amon, room N-13 of the Hidden Temple', 'palladium-fantasy', NULL, '1st level priest of darkness/Amon', 1, 'Diabolic', NULL, NULL, NULL, '{"PP":20}', 11, NULL, NULL, NULL, NULL, 9, NULL, '{"strike":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. Other attributes are average (not printed). A.R. 9 is his soft leather armour (S.D.C. 20). No race is printed on his line; the area is held by a band of goblins.', NULL, NULL, NULL, '1st level priest; his only spell is paralysis, which can be cast twice per day.', NULL, NULL, NULL, 'Soft leather armour (A.R. 9, S.D.C. 20); short sword and dagger (no damage printed).', '30 gold', NULL, NULL, NULL, 'A junior priest of Amon with a room of his own (N-13) among the goblin band in the northern section of the Hidden Temple. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('mintuu', 'Mintuu', NULL, 'Priest of darkness, room N-14 of the Hidden Temple', 'palladium-fantasy', NULL, '2nd level priest of darkness', 2, 'Miscreant', NULL, NULL, NULL, NULL, 17, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Attributes are average (not printed). No race is printed on the line; the area is held by a band of goblins.', NULL, NULL, NULL, 'Spells: 3 daily, cloud of slumber, and wind rush.', NULL, NULL, NULL, 'A pint of goblin moonshine.', '21 gold', NULL, 'His acolyte Tilla', NULL, 'The senior priest of darkness among the goblin band in the northern section of the Hidden Temple, sharing room N-14 with an acolyte. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('tilla-hidden-temple', 'Tilla', NULL, 'Acolyte of the priest of darkness, room N-14 of the Hidden Temple', 'palladium-fantasy', NULL, 'Acolyte', NULL, 'Miscreant', NULL, NULL, NULL, '{"PP":23}', 9, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":1,"strike":4,"parry":4,"dodge":4}', 'First-edition figures, as printed. Other attributes are average (not printed). No spells. No race is printed on the line; the area is held by a band of goblins.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The priest Mintuu', NULL, 'The acolyte who shares room N-14 with the priest Mintuu in the northern section of the Hidden Temple. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.150'),
('tyrod', 'Tyrod', NULL, 'Young pixie of the Mulberry Trees, the Forest of Enchantment', 'palladium-fantasy', 'Pixie', NULL, NULL, 'Anarchist', NULL, NULL, NULL, '{"IQ":10,"ME":5,"MA":6,"PS":1,"PP":17,"PE":4,"PB":14,"Spd":13}', 16, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Brash and boastful, hooked on honey and sweets, and a teller of tall tales about himself; means well and stays loyal, but panics, wanders off and talks at the worst moments.', NULL, NULL, 'A pixie who has never left the Forest of Enchantment and has a 51% chance of attaching himself to a party met among the Mulberry Trees, whatever they say. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.154'),
('malt-the-spriggan', 'Malt the Spriggan', NULL, 'Builder of the Monument of Stone, beyond the Forest of Enchantment', 'palladium-fantasy', 'Spriggan', NULL, NULL, 'Unprincipled', NULL, NULL, NULL, '{"IQ":5,"ME":6,"MA":3,"PS":28,"PP":12,"PE":20,"PB":7,"Spd":4}', 60, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":2}', 'First-edition figures, as printed. Attacks per melee: two or by magic. Other spriggan abilities are not printed here; the book refers to the Palladium R.P.G. p.228.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Heavy iron mallet, large hand pick, a sack of tools.', NULL, 'Gruff and bad-tempered on the surface but secretly thrilled by praise of his monument; insults to it earn a clout, and damage to a pillar sends him berserk.', NULL, NULL, 'A spriggan 63 years into raising a five-mile ring of 30 ft stone pillars in the valley past the Forest of Enchantment; a 40% chance of meeting him there hauling a slab. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.155'),
('uncle-basil', 'Uncle Basil', 'Basil Lehorton', 'Stable owner and head of Uncle Basil''s Traveling Market, below the Place of Magic', 'palladium-fantasy', 'Human', '8th level Merchant, 4th level Mind Mage', 8, 'Miscreant', NULL, NULL, NULL, '{"IQ":16,"ME":15,"MA":10,"PS":11,"PP":11,"PE":11,"PB":8,"Spd":8}', 59, NULL, NULL, NULL, 63, 9, NULL, '{"attacks":2}', 'First-edition figures, as printed. +1 to save vs. spell magic and psionics. Attacks are 2 hand to hand or 2 psionic. A.R. 9 is his soft leather armour (S.D.C. 20).', '[{"name":"Forgery","pct":74},{"name":"Pick Pockets","pct":62},{"name":"Math","pct":93},{"name":"Recognize Weapon Quality","pct":70},{"name":"Recognize Precious Metal/Stones","pct":71},{"name":"Speaks all languages","pct":94}]', 'Forgery is printed 74/34%. Horsemanship: general, no percentage printed.', NULL, NULL, '4th level Mind Mage, I.S.P. 63; powers not listed. The text has him keep a mind block up, mind-wipe his merchants and turn invisible.', NULL, NULL, 'Soft leather armour (A.R. 9, S.D.C. 20); silver dagger, staff or cross bow (no damage printed).', '500 gold and 2000 in jewelry carried; 1000-6000 gold in an iron box (S.D.C. 350) bolted to his office floor at the stables.', 'Outwardly jolly and chatty, underneath a sly and crooked self-server.', 'His ogre blacksmith Tinthermin and six stable hands', NULL, 'A con-man who runs the traveling market in the gorge near Tamaran at the foot of the trail to the Place of Magic, cheating travellers out of stabled mounts and fleeing invisible to fight with psionics when cornered. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.157'),
('blacksmith-tinthermin', 'The Blacksmith Tinthermin', NULL, 'Blacksmith at Uncle Basil''s Stables, Uncle Basil''s Traveling Market', 'palladium-fantasy', 'Ogre', '3rd level Thief', 3, 'Miscreant', NULL, NULL, NULL, '{"IQ":8,"PS":24}', 35, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":2,"damage":9}', 'First-edition figures, as printed. Other attributes are average (not printed). No armour.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'No armour; giant claymore or large iron hammer.', NULL, NULL, 'Uncle Basil and his six stable hands', NULL, 'The ogre smith of Uncle Basil''s stables in the traveling market below the Place of Magic, who backs his employer in a fight without being ready to die for him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.157'),
('serpent-man-leader-with-the-blue-blade', 'Serpent Man Leader with the Blue Blade', NULL, 'Elder leader of the serpent men, the Secret Complex of the Old Ones', 'palladium-fantasy', 'Serpent Man', NULL, NULL, 'Unprincipled', NULL, NULL, NULL, NULL, 32, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Standard stats: otherwise as the Serpent Men block on p.158. The blue blade adds +1 to all saving throws.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The blue blade, a rune sword: I.Q. 10, indestructible, does 4-24, adds +1 to all saving throws, possesses clerical abilities, good alignment (see rune weapons, Palladium R.P.G. p.137).', NULL, 'Neither commands nor understands his sword; the two simply cooperate, and the blade looks after the tribe and its eggs.', 'The other elder leader and the serpent man tribe', NULL, 'One of two elder leaders of the serpent men living with their families in chamber 22 of the Secret Complex of the Old Ones, armed with a rune sword found in the old weapons room. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.160'),
('serpent-man-leader-of-the-red-sword', 'Serpent Man Leader of the Red Sword', NULL, 'Elder leader of the serpent men, the Secret Complex of the Old Ones', 'palladium-fantasy', 'Serpent Man', NULL, NULL, 'Unprincipled', NULL, NULL, NULL, NULL, 39, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Standard stats: otherwise as the Serpent Men block on p.158. The red blade adds +1 to all saving throws.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The red blade, a rune sword: I.Q. 14, indestructible, does 4-24 damage, adds +1 to all saving throws, possesses air elemental magic, miscreant alignment (see Palladium R.P.G. p.137).', NULL, 'Served and undermined by his own sword, which would gladly engineer his death to reach a more adventurous, less honourable owner.', 'The other elder leader and the serpent man tribe', NULL, 'One of two elder leaders of the serpent men living with their families in chamber 22 of the Secret Complex of the Old Ones, armed with a rune sword found in the old weapons room. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.160'),
('hunter-of-the-eternity-sword', 'The Hunter of the Eternity Sword', NULL, 'Cursed stalker of whoever takes the Eternity Sword, the Secret Complex of the Old Ones', 'palladium-fantasy', NULL, '10th level Assassin, 4th level Healer', 10, 'Miscreant', NULL, NULL, NULL, NULL, 70, NULL, NULL, NULL, NULL, 10, NULL, '{"attacks":4,"strike":5,"parry":5,"dodge":5,"damage":2}', 'First-edition figures, as printed. +4 to save vs. psionics/insanity. Attributes: all above average (no figures printed). A.R. 10 is his hard leather armour (S.D.C. 30).', '[{"name":"Disguise","pct":73},{"name":"Prowl","pct":92},{"name":"Pick Locks","pct":77},{"name":"Track","pct":83},{"name":"Use Poison","pct":95}]', 'Disguise is printed 73/38% and Track 83/27%. Several W.P. skills to match his use of weapons.', 'Bound to the Eternity Sword by long use: he always knows where it is and can forbid it to turn its spells on him.', NULL, NULL, NULL, NULL, 'Hard leather armour (A.R. 10, S.D.C. 30); 4 daggers, hippe pole arm, morning star, goupillon flail; Dragon''s breath poison.', NULL, 'Shrewd, careful and thoroughly professional; strikes when the target is alone or asleep, pulls back to recover instead of dying in a fight, and never loses on purpose.', NULL, NULL, 'The printed name is simply The Hunter: the first thief of the Eternity Sword, an assassin held in limbo and loosed whenever someone lifts the blade in area 24 of the Secret Complex of the Old Ones, compelled to kill the bearer and carry it back. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.161'),
('sir-ivon-taper', 'Sir Ivon Taper', NULL, 'Leader of the Small Military Fort (7), the Place of Magic', 'palladium-fantasy', NULL, '5th level knight', 5, 'Scrupulous', NULL, NULL, NULL, NULL, 38, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Nothing but level, hit points and alignment is printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'His garrison of 36 foot soldiers, 24 light cavalry men and 24 short bowmen, all fourth level mercenaries', NULL, 'The knight in charge of the small fort numbered 7 on the Place of Magic map, on the approach by the gorge. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.164'),
('prodo-the-troll', 'Prodo the Troll', NULL, 'Head of the Secret Troll Bridge racket, the Place of Magic', 'palladium-fantasy', 'Troll', '3rd level mercenary', 3, 'Miscreant', NULL, NULL, NULL, '{"IQ":10,"PS":23,"PP":14,"PE":15,"Spd":4}', 47, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":2,"damage":9,"parry":2,"dodge":2}', 'First-edition figures, as printed. Other attributes are average (not printed). A.R. 12 is his studded leather armour (S.D.C. 38).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Studded leather armour (A.R. 12, S.D.C. 38); giant flamberge, battle axe, dagger.', '150 gold on person', 'Full of himself, mouthy and forever cracking jokes; looks far tougher than he is and never fights to the death.', 'Four changeling thieves posing as trolls (30, 24, 29 and 36 hit points)', NULL, 'The troll who runs the extortion racket at the rope bridge over the gorge a mile west of the main entrance to the Place of Magic, selling illicit passage for about a third of a traveller''s valuables. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.164'),
('latimur-karlye', 'Latimur Karlye', NULL, 'Owner of Latimur''s Tavern, the Carnival, the Place of Magic', 'palladium-fantasy', 'Human', '12th level Merchant, 6th level Scholar', 12, 'Unprincipled', '50', NULL, NULL, '{"IQ":14,"MA":24,"ME":9,"Spd":4}', 63, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":2}', 'First-edition figures, as printed. Other attributes are average (not printed). Bonuses are printed as: W.P. knife +5 to strike, +4 to parry, +6 to strike (strike appears twice), 80% chance of people trusting him. Magic talisman +3 vs. circles and wards. A.R. 12 is special studded leather armour (S.D.C. 48) that he never wears. Only uses the knife.', '[{"name":"Speaks all languages except wolfen, troll and faerie","pct":100},{"name":"Read and Write southern, western, elven and dwarven","pct":90},{"name":"Math","pct":98},{"name":"Forgery","pct":90},{"name":"Demon, Devil, Faerie Lore","pct":94}]', 'Forgery is printed 90/46%. W.P. knife.', NULL, NULL, NULL, NULL, NULL, 'Special studded leather armour (A.R. 12, S.D.C. 48), never worn; dwarven short sword +2 to strike, parry, and damage; magic dagger that spits lightning 3X daily; mace; dwarven battle axe +4 to damage; magic talisman +3 vs. circles and wards.', '200 to 800 gold on his person; 3000-12,000 gold on the premises and a fortune in imported liquor.', 'Warm, cheerful, open-handed and kind; mad for adventure stories and puzzles, sharp at spotting crooks, and discreet with what he learns.', 'His daughter LuCinda (5th level merchant, scrupulous), a loyal bartender (ex-4th level mercenary, scrupulous), and many powerful patrons of the community', NULL, 'A stout little tavern keeper in the Carnival at the Place of Magic and a keen amateur sleuth, who trades free food and drink for a good tale and quietly helps anyone with a real mystery. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.164-165'),
('the-mystic-ki-rel', 'The Mystic', 'Ki-rel', 'Alchemist of the Alchemist Shop (O), Place of Magic', 'palladium-fantasy', 'Elf', '10th level Scholar, 10th level Alchemist, 3rd level Wizard, 6th level Diabolist, Minor Psionic', 10, 'Anarchist', '400', NULL, NULL, '{"IQ":16,"ME":12,"PS":14,"PP":13,"PB":18,"Spd":12}', 67, NULL, NULL, NULL, 43, 12, NULL, '{"attacks":2,"strike":3,"parry":3,"dodge":3}', 'First-edition figures, as printed. Attacks are 2 hand to hand or 1 spell. +6 to save vs. all magic and psionics (includes the bonus from a magic medallion). The +3 to strike, parry and dodge applies with staff or knives. A.R. 12 is his magic cloak of protection (S.D.C. 50). Other attributes are average (not printed).', '[{"name":"Speaks all languages","pct":100},{"name":"Reads and writes runes, mystic symbols, elven, dwarven, southern and western","pct":100},{"name":"Recognizes precious metals, stones, poisons, plants","pct":100},{"name":"Use Poison","pct":100}]', 'Also an authority on demon lore, racial histories and religious doctrine (no percentage printed).', NULL, '3rd level Wizard, 6th level Diabolist; can cast 5 spells per day. Spells: the five common knowledge spells plus Sense Evil, Globe of Silence, Ventriloquism, Phantom, Magic Net, Magic Pigeon, Fire Ball, Call Lightning, Darkness, Turn Self Into Mist, Fly as an Eagle. His shop entry (p.165) adds that he already knows the power circles of invisibility and knowledge, and lists the wards and circles he sells or teaches.', 'Minor Psionic, I.S.P. 43; powers not listed.', NULL, NULL, 'Magic cloak of protection with invisibility (A.R. 12, S.D.C. 50, impervious to fire); Thunder rod (gnarled wood staff with mystic symbols, teleports 2X daily); pouch of powders: pixie, sneezing and fire dust, four smoke bombs, one fume of weakness; two normal daggers in boot and belt; boots of fleet feet; medallion of protection from magic (+3).', '200-800 gold on his person; 100,000 to 400,000 in gold and gems available when needed.', 'Sharp, grasping and self-serving, yet scrupulously exact about what he sells; deals with anyone, good or evil, if it gets him what he is after.', 'His weasel familiar; invisible guardians he summons (air elemental, devil or demon). Animal companion: The Mystic''s Weasel Familiar (weasel, 13 hit points; +6 dodge; prowl 80%).', NULL, 'A frail-looking, ill-tempered elf who runs the finest alchemist shop in the Timiro Kingdom at the Place of Magic and guards it with wards and summoned things. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.167'),
('tanash-loquel', 'Tanash LoQuel', NULL, 'Weaponsmith of the Armour of the Exotic (Z), Place of Magic', 'palladium-fantasy', 'Dwarf', '6th level Assassin', 6, 'Miscreant', NULL, NULL, NULL, '{"IQ":12,"PE":18,"PS":15,"PP":14}', 63, NULL, NULL, NULL, NULL, 14, NULL, '{"attacks":3,"damage":2}', 'First-edition figures, as printed. +2 to save vs. magic and poison. W.P. bonuses are not included but average about +3 to strike and parry. A.R. 14 is his magic leather armour (S.D.C. 180). Other attributes are average (not printed). The shop entry spells the name "Tanash Lo Quel".', '[{"name":"Use Poison","pct":70},{"name":"Speaks and reads dwarven","pct":100},{"name":"Speaks goblin and southern","pct":100}]', 'W.P. short sword, W.P. ball and chain, W.P. knives, W.P. sling, prowl (no percentage printed).', NULL, NULL, NULL, NULL, NULL, 'Magic leather armour (A.R. 14, S.D.C. 180); flail; glowing short sword; 3 silver coated daggers; sling; ring of fire imperviousness.', 'Always has 2000-8000 cash on hand.', 'Tough and reasonably amiable in business, but loathes elves and will not trade with them.', 'Three loyal 4th level dwarven soldiers: Mithc, Khand and Gunth', 'Elves', 'A semi-retired assassin who bankrolled his own arms and armour shop at the Place of Magic and can still be hired for a killing if the fee suits. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.167-168'),
('mithc', 'Mithc', NULL, 'Soldier employed at the Armour of the Exotic (Z), Place of Magic', 'palladium-fantasy', 'Dwarf', '4th level Soldier', 4, 'Anarchist', NULL, NULL, NULL, NULL, 50, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tanash LoQuel', NULL, 'One of three dwarven soldiers on the payroll of the weaponsmith Tanash LoQuel at the Place of Magic, and wholly loyal to him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.168'),
('khand', 'Khand', NULL, 'Soldier employed at the Armour of the Exotic (Z), Place of Magic', 'palladium-fantasy', 'Dwarf', '4th level Soldier', 4, 'Miscreant', NULL, NULL, NULL, NULL, 31, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tanash LoQuel', NULL, 'One of three dwarven soldiers on the payroll of the weaponsmith Tanash LoQuel at the Place of Magic, and wholly loyal to him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.168');
INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('gunth', 'Gunth', NULL, 'Soldier employed at the Armour of the Exotic (Z), Place of Magic', 'palladium-fantasy', 'Dwarf', '4th level Soldier', 4, 'Diabolic', NULL, NULL, NULL, NULL, 34, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Tanash LoQuel', NULL, 'One of three dwarven soldiers on the payroll of the weaponsmith Tanash LoQuel at the Place of Magic, and wholly loyal to him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.168'),
('bedlo', 'Bedlo', NULL, 'Owner of Bedlo''s Livery (18), Place of Magic', 'palladium-fantasy', NULL, '10th level Merchant', 10, 'Anarchist', NULL, '6 ft', NULL, NULL, 49, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Race is not printed (described only as a man).', NULL, 'Horsemanship: knight.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Jovial, but a hard bargainer over horseflesh.', NULL, NULL, 'A stout, nobly born livestock dealer who runs the largest livery at the Place of Magic and pays very little for any horse that is not a war or race animal. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.168'),
('raven-darkhold', 'Raven Darkhold', 'Sharagar Darkhold', 'Prince of the Western Empire; summoner in residence (33) at the Place of Magic', 'palladium-fantasy', 'Human', '7th level Summoner, 5th level Wizard, 7th level Pseudo Mind Mage', 7, 'Diabolic', '40', '6 ft 4 in', NULL, NULL, 96, NULL, NULL, NULL, 66, 12, NULL, '{"attacks":2,"strike":2,"parry":2,"dodge":2}', 'First-edition figures, as printed. Attacks are 2 hand to hand or 2 psionic, or 2 spell attacks. +2 vs. all magic; +2 to strike, parry or dodge. A.R. 12 is his cloak of protection (S.D.C. 50, impervious to fire); when adventuring he instead wears magic soft leather armour, A.R. 15, S.D.C. 210.', '[{"name":"Pick Locks","pct":80},{"name":"Forgery","pct":90},{"name":"Prowl","pct":60},{"name":"Read and write western, elven, dwarven","pct":100},{"name":"Speaks western, southern, eastern, elven, dwarven and goblin","pct":100},{"name":"Recognize and use poison","pct":100}]', 'Forgery is printed 90/46%. Horsemanship: knight.', NULL, 'Can cast 8 spells daily, +2 spell strength. Common knowledge spells plus reduce self, see the invisible, chameleon, armour of Ithan, turn self into mist, call lightning, mask of deceit, death trance, familiar link. Circles: +2 circle strength; all protection and summoning; power circles: healing, knowledge, pain.', 'Limited to levels 1-3 (major psionic). Aura of truth, detect psionics, meditate, object read, presence sense, resist cold and fatigue, see aura, bio-regenerate, levitate, limited telekinesis, mind block, nightvision, mental bolt of force, turn invisible, precognition, evil eye (all).', NULL, NULL, 'Cloak of protection (A.R. 12, S.D.C. 50, impervious to fire) or magic soft leather armour (A.R. 15, S.D.C. 210); twin silver plated magic daggers, falchion, crossbow, trident, three daggers. Potions: healing (4), youthful appearance (2), mute (1). Scrolls: immobolize (1), multiple image (2), charm (1), strength of Utgard Loki (2), stone to flesh (1). Books on dwarven history, personal items, pegasus medallion (fly 4X daily).', '1 Old Kingdom Dragon Coin worth 5000 gold, 20 Western 100 gold pieces, and 80,000 in coin and gems hidden and guarded in his residence.', 'Arrogant, secretive and vindictive beneath a cool surface; trusts no one, scorns soldiers and non-Westerners, and lies with ease.', 'Three summoned demons: Polt the Baal-Rog, and Ingus and Sucram the Incubus and Succubus; Caliph Alsto Stone sends him information', NULL, 'A Western nobleman and notorious loner at the Place of Magic who found the Old One years ago, poisoned his elven partner to stop it being woken, and now will not set foot in the ruins. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.168-169'),
('polt-the-baal-rog', 'Polt the Baal-Rog', NULL, 'Demon servant of Raven Darkhold, Place of Magic', 'palladium-fantasy', 'Baal-Rog (demon)', NULL, NULL, 'Anarchist', NULL, NULL, NULL, NULL, 74, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Only alignment and Hit Points are printed; the book refers to the Palladium R.P.G., page 177, for the rest.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Raven Darkhold', NULL, 'One of three demons the summoner Raven Darkhold calls up at the Place of Magic to run his errands, and unusually faithful to him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.169'),
('ingus-the-incubus', 'Ingus the Incubus', NULL, 'Demon servant of Raven Darkhold, Place of Magic', 'palladium-fantasy', 'Incubus (demon)', NULL, NULL, 'Miscreant', NULL, NULL, NULL, NULL, 44, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Only alignment and Hit Points are printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Raven Darkhold', NULL, 'One of three demons the summoner Raven Darkhold calls up at the Place of Magic to run his errands, and unusually faithful to him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.169'),
('sucram-the-succubus', 'Sucram the Succubus', NULL, 'Demon servant of Raven Darkhold, Place of Magic', 'palladium-fantasy', 'Succubus (demon)', NULL, NULL, 'Miscreant', NULL, NULL, NULL, NULL, 39, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. Only alignment and Hit Points are printed.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Raven Darkhold', NULL, 'One of three demons the summoner Raven Darkhold calls up at the Place of Magic to run his errands, and unusually faithful to him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.169'),
('black-death', 'Black Death', NULL, 'Undisputed leader of the pseudo-demons of the canals (C-16), Place of Magic', 'palladium-fantasy', 'Pseudo-demon (former human)', '6th level Mind Mage', 6, 'Diabolic', NULL, '11 ft', NULL, '{"IQ":11,"ME":12,"PS":20,"PB":6,"PP":9}', 33, NULL, NULL, NULL, 87, 14, NULL, '{"attacks":2,"damage":5}', 'First-edition figures, as printed. 2 attacks per melee +1 with tail. +2 on all saves, 1/2 damage from cold and fire. A.R. 14 is his ogre double mail (S.D.C. 52); his skin alone is A.R. 12. Abilities: See the Invisible, Turn Dead. Weapon proficiencies: Knife +2 to strike, +2 parry/dodge, +2 throw; Staff +2 to strike, +3 parry/dodge.', NULL, NULL, 'Sees invisible things and can turn the dead; bites and lashes with a tail.', NULL, 'All psionics level 1-6, I.S.P. 87 (printed under "Spells").', NULL, NULL, 'Ogre double mail (A.R. 14, S.D.C. 52); thunder rod/metal staff; 3 knives; bastard sword. Pixie dust (2); gem studded Old Kingdom Dragon coin in a necklace with wards of sleep, alarm (sound) and death, all at 4th level.', NULL, 'A lecher who enslaves women; terrified of reptiles and of open spaces.', 'Banderdash (right hand man), Kragg (counsel)', 'Kyl-Lebash, his second in command, wants his place', 'The scaly black, red-eyed ruler of the canal people under the Place of Magic; goods in his quarters suggest he was once a man called Franklin Tobar. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.173'),
('kyl-lebash', 'Kyl-Lebash', NULL, 'Second in command of the pseudo-demons of the canals (C-13), Place of Magic', 'palladium-fantasy', 'Pseudo-demon (former elf)', '5th level Assassin', 5, 'Diabolic', NULL, '8 ft', NULL, '{"IQ":12,"PP":23,"PS":20,"Spd":16}', 39, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3,"strike":4,"parry":4,"dodge":4,"damage":7}', 'First-edition figures, as printed. +4 on all strike/parry/dodge, critical attack from behind, kick attack, 1/2 damage from cold and fire. +2 on all saves. A.R. 12 is his leathery skin. Abilities: Animate and Control Dead, Turn Invisible. Spells: none. Weapon proficiencies: Knife +6 to strike, +5 parry/dodge, +6 throw; Blunt +7 to strike, +5 parry/dodge, +5 throw; Spear/Fork +6 strike, +7 parry/dodge, +6 throw; Ball & Chain +7 to strike, +5 to parry/dodge. The name is printed "Kyl-Lebash" twice (order of rule, C-13) and "Kyl-Lebash" at the head of his block. His block and his own entry spell the name this way; the order-of-rule list adds an n before the s.', NULL, NULL, 'Raises and commands corpses and can vanish from sight; has fangs and claws.', NULL, NULL, NULL, NULL, 'Mace & chain, trident, 3 knives, mace. Possessions: none (his room C-13 holds a trunk of valuables).', NULL, 'Comes across as chatty and affable; fears dogs, water and worms and hates wolfen.', NULL, 'Black Death, whose position he covets; wolfen', 'A dark red, leather-skinned former elf who ranks second among the canal people under the Place of Magic and schemes for the top spot. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.173'),
('banderdash', 'Banderdash', NULL, 'Third in rank of the pseudo-demons of the canals (C-14), Place of Magic', 'palladium-fantasy', 'Pseudo-demon (former ogre)', '3rd level Mercenary', 3, 'Miscreant', NULL, '14 ft', NULL, '{"IQ":13,"PS":22,"PE":20,"Spd":19}', 44, NULL, NULL, NULL, NULL, 15, NULL, '{"attacks":2,"damage":7}', 'First-edition figures, as printed. Attacks are 2 normal + 1 tail. +3 against magic or poison, 1/2 damage from cold or fire, +2 on all saves. A.R. 15 is his exo-skeleton. Abilities: Impervious to fire, Fly. Spells: none. Weapon proficiencies: Knife +1 to strike, +1 throw; Large Sword +1 to strike, +1 parry/dodge; Blunt +1 to strike, +1 parry/dodge. 72% chance of a semi-functional berserker rage when frustrated or angry.', NULL, NULL, 'Flies and cannot be burned; armoured black shell, fangs, claws and a tail.', NULL, NULL, NULL, NULL, '2 invisible magic daggers that return when thrown, invisible claymore, giant size war hammer, 2 normal daggers. Possessions: none.', NULL, 'Loathes the supernatural, gods and demons above all; afraid of females and reptiles; prone to berserk fits.', 'Black Death (friend and protector)', NULL, 'A towering ex-ogre in a black exo-skeleton with glowing yellow eyes, bodyguard and friend to the leader of the canal people under the Place of Magic. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.173-174'),
('benilli', 'Benilli', NULL, 'Fourth in rank of the pseudo-demons; master of the floating town (C-33), Place of Magic', 'palladium-fantasy', 'Pseudo-demon (former dwarf)', '4th level Mercenary', 4, 'Miscreant', NULL, '10 ft', NULL, '{"IQ":8,"PS":20,"PP":15,"PB":4}', 50, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":2,"parry":2,"dodge":2,"damage":7}', 'First-edition figures, as printed. +2 on all parry/dodge, 1/2 damage from cold or fire, +2 on all saves. A.R. 12 is his scaly skin. Abilities: See the Invisible, Fly. Spells: none. Weapon proficiencies: Short sword +2 to strike, +2 parry/dodge, +1 throw; Battle axe +2 to strike, +1 parry/dodge, +2 throw; Crossbow +3 to strike, rate of fire is 4.', NULL, NULL, 'Flies and sees the invisible; pale scaled hide, sharp teeth and big claws.', NULL, NULL, NULL, NULL, 'Battle axe, short sword, crossbow and 24 bolts. Possessions: none (his house at C-33 holds his goods).', NULL, 'Fanatically tidy; frightened of clergy and of the undead.', NULL, NULL, 'A red-eyed, white-scaled former dwarf who lords it over 23 low caste subjects on the rafts of the canals under the Place of Magic. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.174'),
('kragg', 'Kragg', NULL, 'Fifth in rank of the pseudo-demons; counsel to Black Death (C-19), Place of Magic', 'palladium-fantasy', 'Pseudo-demon (former human)', '5th level Wizard', 5, 'Anarchist', NULL, '10 ft', NULL, NULL, 46, NULL, NULL, NULL, NULL, 10, NULL, '{"attacks":2}', 'First-edition figures, as printed. Attributes: Average. Attacks are 2 hand to hand and 2 magic. 1/2 damage from fire or cold, +2 on all saves, +2 spell strength. A.R. 10 is his lumpy skin. Abilities: Rodent Metamorph, Animate and Control Dead (his room entry says he can control 2-12 dead). Weapon proficiencies: Knife +1 to strike, +1 throw.', NULL, NULL, 'Can become a rodent and raise the dead to serve him; sharp teeth and little horns.', '5th level Wizard, +2 spell strength. Spells: Slumber, Daylight, Tongues, Decipher Magic, Sense Magic, Reduce Self, Weightlessness, Swim as Fish, Mask of Deceit, Cloud of Smoke, Fireball.', NULL, NULL, NULL, '4 silver daggers. Possessions: see room C-19 (trunk with potions and scrolls).', NULL, 'Uninterested in power and content to advise whoever leads; cannot bear closed rooms and also fears cats and dogs; always neatly dressed.', 'Black Death', NULL, 'A pale, lumpy-skinned wizard who lives on an open platform in the great cavern of the canals under the Place of Magic because enclosed spaces terrify him. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.174'),
('brabdock-silkplow', 'Brabdock Silkplow', NULL, 'Sixth in rank of the pseudo-demons (C-21), Place of Magic', 'palladium-fantasy', 'Pseudo-demon (former human)', '4th level Diabolist', 4, 'Diabolic', NULL, '11 1/2 ft', NULL, NULL, 37, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":2,"strike":1,"parry":1,"dodge":1,"damage":9}', 'First-edition figures, as printed. Attacks are 2 +1 for tail. +1 on all saves, +2 against circles, +3 against wards, 1/2 damage from fire or cold; claws, horns, cloven hooves. A.R. 12 is his scaly skin. Abilities: See the Invisible, Healing Touch, Recognize Enchantment 40%. Spells: none. Weapon proficiencies: Knives +2 to strike, +1 parry/dodge, +2 thrown; Ball and Chain +2 to strike, +1 parry/dodge.', '[{"name":"Recognize Enchantment","pct":40}]', NULL, 'Sees the invisible and heals by touch; scaled, with claws, horns, hooves and a tail.', '4th level Diabolist; his lair C-21 is warded (alarm, despair, cold) and holds a Circle of Protection from Good.', NULL, NULL, NULL, '2 giant sized daggers, giant sized ball and chain. Possessions: see C-21.', NULL, 'Sly, vicious and ambitious.', 'Sheela, his pseudo-demon mate', NULL, 'A climbing ward-maker among the canal people under the Place of Magic, who keeps a heavily warded house on a rock platform. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.174'),
('soworn', 'Soworn', NULL, 'Elected leader of the good pseudo-demons at C-43 in the canals, Place of Magic', 'palladium-fantasy', 'Pseudo-demon (former human)', '4th level Mind Mage', 4, 'Principled', NULL, '10 ft', NULL, '{"IQ":18,"ME":20}', 42, NULL, NULL, NULL, 58, NULL, NULL, NULL, 'First-edition figures, as printed. +2 save vs. psionics or insanity. She is the only pseudo-demon with no phobias or insanity.', NULL, NULL, 'Contagion-given abilities: extra large claws; rodent metamorph; impervious to fire.', NULL, '4th level Mind Mage, 58 I.S.P.; has all psionics through level 4.', NULL, NULL, NULL, NULL, 'Wary of strangers but welcoming to the honourable; urges the healthy to turn back.', NULL, NULL, 'A pseudo-demon standing 10 ft, once a human, met at C-43 in the canals beneath the Place of Magic. A woman chosen to lead 48 good-aligned pseudo-demons who hold the northeast canals against the rest. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.180'),
('magot-of-the-tunnels', 'Magot of the Tunnels', NULL, 'Greater demon trapped in room T-9 of the tunnels, Place of Magic', 'palladium-fantasy', 'Magot (greater demon)', NULL, NULL, NULL, NULL, '20 ft', NULL, '{"IQ":7,"Spd":24}', 55, NULL, NULL, NULL, NULL, 14, NULL, '{"attacks":3,"damage":8}', 'First-edition figures, as printed. +3 on all saves. Its eye attack petrifies (turns to stone) for 20 melees anyone who fails to save vs. magic. Listed abilities: nightvision 120ft, impervious to fire, see invisible, turn invisible, turn into mist, bio-regeneration, knows all languages; it can also dimensional teleport back to hell. The book gives no name; "Magot" is the kind.', NULL, NULL, 'Sees in the dark and sees the unseen, cannot be burned, can vanish or become mist, heals itself, and understands every tongue. Its gaze turns victims to stone for a time.', NULL, NULL, NULL, NULL, NULL, NULL, 'Slaughters everything that moves once freed, and flees home only when facing destruction.', NULL, 'Caliph Alsto Stone, who penned it in', 'A huge maw on three thick legs with eyes on stubby tentacles, held behind a protection circle in the tunnels under the Place of Magic until someone opens the door and walks in. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.184'),
('linda-belamche', 'Linda Belamche', NULL, 'Vampire priestess of Utu in the Kingdom of the Walking Dead (T-25H), Place of Magic', 'palladium-fantasy', 'Vampire (appears human)', '2nd level Priestess and Vampire', 2, 'Anarchist', NULL, NULL, NULL, '{"IQ":9,"PB":19}', 48, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3,"strike":2,"parry":3,"dodge":3,"damage":6}', 'First-edition figures, as printed. A.R. 12; affected only by silver, holy or magic weapons. +4 on all saves, +1 against spells, circles and wards. Listed abilities: healing touch (1-8), bio-regeneration (1-6), change to mist, bat or wolf metamorph, see invisible, impervious to cold, fire does 1/2 damage, hypnotic gaze, turn dead (84%), animate/control dead (6-46) 71%; speaks southern, western, elf and dwarf; can summon 20-120 bats, 4-24 wolves, or 40-240 rats. (Her entry prints "6-46" where the other vampires print "6-48".) Weapon proficiencies: Knives +3 strike, +4 to parry, +4 thrown.', '[{"name":"Turn Dead","pct":84},{"name":"Animate/Control Dead","pct":71}]', NULL, 'Mends itself and others, shifts into mist, bat or wolf, perceives the unseen, shrugs off cold and half of any fire, entrances with a look, and commands corpses, bats, wolves and rats.', 'Spells: silence, water to wine, and darkness.', NULL, NULL, NULL, '1 curved dagger. Light grey silk robes, a thin bronze belt, and a matched set of carved ivory necklaces and earrings (worth 400 gold).', NULL, 'Polite and agreeable, playing the bashful innocent.', NULL, NULL, 'A pallid, strawberry-blonde woman, in truth a vampire who serves Utu, Lord of the Dead, in the sealed rooms of the tunnels under the Place of Magic. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.186'),
('lardo-panedor', 'Lardo Panedor', NULL, 'Vampire knight in the Kingdom of the Walking Dead (T-25J), Place of Magic', 'palladium-fantasy', 'Vampire (appears human)', '6th level Knight (vampire)', 6, 'Diabolic', NULL, NULL, NULL, '{"IQ":14}', 44, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3,"strike":2,"parry":3,"dodge":3,"damage":6}', 'First-edition figures, as printed. A.R. 12; affected only by silver, holy or magic weapons. +4 on all saves, +3 against spells/circles/wards. Listed abilities: healing touch (1-8), bio-regeneration (1-6), change to mist, bat or wolf metamorph, see invisible, impervious to cold, fire does 1/2 damage, hypnotic gaze, turn dead (84%), animate/control dead (6-48) 71%; speaks southern, western, elf and dwarf; can summon 20-120 bats, 4-24 wolves, or 40-240 rats. Spells: none. Weapon proficiencies: Short Sword +6 to strike, +6 to parry, +3 thrown; Knives +5 to strike, +6 parry, +4 thrown.', '[{"name":"Turn Dead","pct":84},{"name":"Animate/Control Dead","pct":71}]', NULL, 'Mends itself and others, shifts into mist, bat or wolf, perceives the unseen, shrugs off cold and half of any fire, entrances with a look, and commands corpses, bats, wolves and rats.', NULL, NULL, NULL, NULL, 'Bastard sword, 2 daggers. Rich dark blue and white suit; ruby ring (worth 1200 gold), jade ring (worth 400 gold), gold dwarven medallion (worth 300, or 1200 gold as an ancient relic).', NULL, 'Vicious and perilous; shuns a fight but kills when he must.', NULL, NULL, 'A gaunt, sour, bearded old man, his long hair gone grey-white, sitting among fine furniture beside his coffin in the tunnels under the Place of Magic. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.186'),
('tol-crac-the-smasher', 'Tol-Crac The Smasher', NULL, 'Ogre vampire in the Kingdom of the Walking Dead (T-25K), Place of Magic', 'palladium-fantasy', 'Ogre Vampire', NULL, NULL, 'Diabolic', NULL, '6 ft', '170 pounds', NULL, 60, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3,"strike":2,"parry":3,"dodge":3,"damage":6}', 'First-edition figures, as printed. Attributes: Average. A.R. 12; affected only by silver, holy or magic weapons. +4 on all saves. Listed abilities: healing touch (1-8), bio-regeneration (1-6), change to mist, bat or wolf metamorph, see invisible, impervious to cold, fire does 1/2 damage, hypnotic gaze, turn dead (84%), animate/control dead (6-48) 71%; speaks southern, western, elf and dwarf; can summon 20-120 bats, 4-24 wolves, or 40-240 rats. Spells: none. Weapon proficiencies: Battle axe +5 to strike, +3 parry/dodge, +6 thrown.', '[{"name":"Turn Dead","pct":84},{"name":"Animate/Control Dead","pct":71}]', NULL, 'Mends itself and others, shifts into mist, bat or wolf, perceives the unseen, shrugs off cold and half of any fire, entrances with a look, and commands corpses, bats, wolves and rats.', NULL, NULL, NULL, NULL, 'Large battle axe. Tan vest and pants, a scroll of flying (6th level).', '1000 gold pieces.', 'Savage and quarrelsome; sets on any party of fewer than four or one that looks worn down.', NULL, NULL, 'An undersized, pale ogre with red hair and beard who sleeps in an outsized open coffin in the tunnels under the Place of Magic. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.186-187'),
('liila-alret', 'Liila Alret', NULL, 'Elf vampire in the Kingdom of the Walking Dead (T-25L), Place of Magic', 'palladium-fantasy', 'Elf Vampire', NULL, NULL, 'Miscreant', NULL, NULL, NULL, '{"PB":21}', 46, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3,"strike":2,"parry":3,"dodge":3,"damage":6}', 'First-edition figures, as printed. A.R. 12; affected only by silver, holy or magic weapons. +4 on all saves. Listed abilities: healing touch (1-8), bio-regeneration (1-6), change to mist, bat or wolf metamorph, see invisible, impervious to cold, fire does 1/2 damage, hypnotic gaze, turn dead (84%), animate/control dead (6-48) 71%; speaks southern, western, elf and dwarf; can summon 20-120 bats, 4-24 wolves, or 40-240 rats. Spells: none. Weapon proficiencies: none. Weapons: none.', '[{"name":"Turn Dead","pct":84},{"name":"Animate/Control Dead","pct":71}]', NULL, 'Mends itself and others, shifts into mist, bat or wolf, perceives the unseen, shrugs off cold and half of any fire, entrances with a look, and commands corpses, bats, wolves and rats.', NULL, NULL, NULL, NULL, 'No weapons. Simple blue cloth dress and gold necklace.', NULL, 'Plays at being gentle and frightened, but is spiteful when pressed.', NULL, NULL, 'The mother of an elven pair, white-haired, grey-eyed and beautiful, who wait in a gaily furnished room of the tunnels under the Place of Magic; both are vampires. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.187'),
('krela-alret', 'Krela Alret', NULL, 'Elf vampire in the Kingdom of the Walking Dead (T-25L), Place of Magic', 'palladium-fantasy', 'Elf Vampire', NULL, NULL, 'Miscreant', NULL, NULL, NULL, '{"PB":23}', 42, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3,"strike":2,"parry":3,"dodge":3,"damage":6}', 'First-edition figures, as printed. A.R. 12; affected only by silver, holy or magic weapons. +4 on all saves. Listed abilities: healing touch (1-8), bio-regeneration (1-6), change to mist, bat or wolf metamorph, see invisible, impervious to cold, fire does 1/2 damage, hypnotic gaze, turn dead (84%), animate/control dead (6-48) 71%; speaks southern, western, elf and dwarf; can summon 20-120 bats, 4-24 wolves, or 40-240 rats. Spells: none. Weapon proficiencies: none. Weapons: none.', '[{"name":"Turn Dead","pct":84},{"name":"Animate/Control Dead","pct":71}]', NULL, 'Mends itself and others, shifts into mist, bat or wolf, perceives the unseen, shrugs off cold and half of any fire, entrances with a look, and commands corpses, bats, wolves and rats.', NULL, NULL, NULL, NULL, 'No weapons. Simple blue cloth dress and gold necklace.', NULL, 'Plays at being gentle and frightened, but is spiteful when pressed.', NULL, NULL, 'The girl child of an elven pair, white-haired, grey-eyed and beautiful, who wait in a gaily furnished room of the tunnels under the Place of Magic; both are vampires. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.187'),
('klak-bathamee', 'Klak Bathamee', NULL, 'Vampire priest of Utu in the Kingdom of the Walking Dead (T-25M), Place of Magic', 'palladium-fantasy', 'Vampire (changeling; appears as a male elf)', '4th level Priest of Utu (vampire)', 4, 'Miscreant', NULL, NULL, NULL, NULL, 50, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":3,"strike":2,"parry":3,"dodge":3,"damage":6}', 'First-edition figures, as printed. Attributes: Average. A.R. 12; affected by silver, holy or magic weapons only. +4 on all saves, +3 against all spells, circles, and scrolls. Curse 24%. Listed abilities: healing touch (1-8), bio-regeneration (1-6), change to mist, bat or wolf metamorph, see invisible, impervious to cold, fire does 1/2 damage, hypnotic gaze, turn dead (84%), animate/control dead (6-48) 71%; speaks southern, western, elf and dwarf; can summon 20-120 bats, 4-24 wolves, or 40-240 rats. Weapon proficiencies: Short sword +5 to strike, +6 parry/dodge, +3 thrown.', '[{"name":"Curse","pct":24},{"name":"Turn Dead","pct":84},{"name":"Animate/Control Dead","pct":71}]', NULL, 'Mends itself and others, shifts into mist, bat or wolf, perceives the unseen, shrugs off cold and half of any fire, entrances with a look, and commands corpses, bats, wolves and rats.', 'Spells: Paralysis, levitate, slumber, immobilize, and wisps of confusion. Scrolls: stone to flesh, extinguish fires, magic pigeon (wizard), armour of ithan (cleric).', NULL, NULL, NULL, 'Kars the Avenger, a lesser holy sword that glows faintly white, expels devils and demons (89% for lesser, 49% for greater types) and automatically senses evil. Black hooded robe; black pearl ring (worth 1200 gold); several scrolls.', NULL, 'Stiffly proper and pious; feigns honour while serving only his own ends.', NULL, NULL, 'A changeling vampire who shows himself as a tall, slender, dark-skinned elf and tends three temples from a bronze coffin behind the altar of Utu in the tunnels under the Place of Magic. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.187'),
('trok', 'Trok', NULL, 'Leader of the minotaurs, the Tunnels (Place of Magic)', 'palladium-fantasy', 'Minotaur', '5th level Mercenary', 5, 'Unprincipled', NULL, NULL, NULL, '{"IQ":10,"ME":21,"PP":16,"Spd":20}', 54, NULL, NULL, NULL, NULL, 12, NULL, '{"strike":3,"parry":3,"dodge":3,"damage":6}', 'First-edition figures, as printed. +4 on rolls against psionics. A.R. 12 is his splint armour (S.D.C. 40). Scythe and scimitar are each +5 to strike; large shield +5 to parry.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Splint armour (A.R. 12, S.D.C. 40); scythe; silver dwarven scimitar; 2 daggers; large shield (+5 parry); medallion of protection from undead.', NULL, 'Sharp-minded and even-handed; faithful to his tribe and to Alsto.', 'Alsto Stone; his wife Kla and sons Brotk and Trokbo', NULL, 'Chief of the minotaur tribe that serves the basilisk Alsto, living with his family in room T-37 of the tunnels. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.189'),
('caliph-alsto-stone', 'Caliph Alsto Stone', NULL, 'Basilisk master of the Tunnels (Place of Magic)', 'palladium-fantasy', 'Basilisk', '3rd level Diabolist', 3, 'Miscreant', NULL, '8 ft', NULL, '{"IQ":17,"PS":22,"PP":12,"Spd":18}', 53, NULL, NULL, NULL, NULL, 10, NULL, '{"attacks":2,"parry":3,"dodge":3,"damage":6}', 'First-edition figures, as printed. Attacks per melee are printed as 2 attacks +1 attack with tail. +1 on all saves, +1 against circles/scrolls, +2 against wards. A.R. 10 is natural armour. W.P. Knives: +3 to strike, +3 parry, +1 thrown.', '[{"name":"Turn dead","pct":80},{"name":"Recognize enchantment","pct":40}]', 'Turn dead is printed "(2-12) 80%". Speaks all languages. W.P. Knives.', 'Petrifies permanently, can become invisible and sees invisible things, heals by touch (1-8), and fights with claws, bite and tail.', 'Spells as printed: activate 5 wards daily as a 3rd level Diabolist.', NULL, NULL, NULL, 'Gold plated dwarven dagger; small pouch; tobacco pouch and pipe; large pouch with basic ward components; 2 smoke bombs; chalk. Usually in silk robes.', '300 gold pieces in a small pouch.', 'Puts on the manner and accent of a Western noble and enjoys muddling intruders by mixing lies with truth until even an honest warning is doubted.', 'Trok''s minotaur tribe; his pseudo-demons', NULL, 'A basilisk diabolist who rules the tunnel level from his warded sanctum, room T-50, served by minotaurs and pseudo-demons. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.190'),
('king-matlock-pryetti', 'King Matlock Pryetti', NULL, 'The Mad Dwarf, ruler of the Armoury (Place of Magic)', 'palladium-fantasy', 'Human', '7th level Soldier', 7, 'Unprincipled (depending on persona)', NULL, '5 ft 3 in', NULL, '{"IQ":9,"ME":15,"MA":12,"PS":17,"PP":16,"PE":12,"Spd":7}', 47, NULL, NULL, NULL, NULL, 17, NULL, '{"attacks":3,"strike":4,"parry":4,"dodge":4,"damage":5}', 'First-edition figures, as printed. Critical strike on 18-20. A.R. 17 is full dwarven plate (S.D.C. 160). W.P. Battle Axe: +7 strike, +6 parry, +3 thrown. W.P. Short sword: +7 strike, +7 parry, +2 thrown. W.P. Knives: +7 strike, +6 parry, +4 thrown. The Helmet of Rurga gives its wearer +2 on all saves.', '[{"name":"Track","pct":70},{"name":"Identify tracks","pct":79},{"name":"Prowl","pct":89}]', 'The three percentages are powers of the Helmet of Rurga, as is speaking all languages. W.P. Battle Axe, W.P. Short sword, W.P. Knives.', NULL, 'Spells: None. Helmet of Rurga: animate and control 10-60 dead (98%); see the invisible; blocks all psionic attacks and probes; magic charms and mental manipulations have no effect.', NULL, NULL, NULL, 'Full dwarven plate armour (A.R. 17, S.D.C. 160); Helmet of Rurga (red and silver great helm, cannot be removed); eternally sharp dwarven battle axe; dwarven short sword; 2 silver daggers; misc. clothing.', NULL, 'Driven mad by the helm, he believes he is a dwarf, loathes elves, and shifts between the helm''s stored personas; he would be lost without it.', 'Sara and Spaz; his living followers and the animated dwarven skeletons', NULL, 'A human soldier trapped in the Helmet of Rurga who reigns over the armoury complex as a dwarf king, commanding skeletons he takes for living troops. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.193'),
('sara-place-of-magic', 'Sara', 'Sara Lynnendal', 'High Council to the Mad Dwarf, the Armoury (Place of Magic)', 'palladium-fantasy', 'Elf', '4th level Diabolist and 4th level Thief', 4, 'Miscreant', NULL, NULL, NULL, '{"IQ":13,"PS":10,"PP":18,"PE":11,"PB":18,"Spd":6}', 64, NULL, NULL, NULL, 32, 9, NULL, '{"attacks":2,"strike":2,"parry":4,"dodge":4}', 'First-edition figures, as printed. +1 save against circles, +2 save against wards, +2 ward strength. Critical strike from behind. A.R. 9 is soft leather armour (S.D.C. 20). W.P. Knives: +4 strike, +6 parry, +2 thrown. W.P. Large swords: +4 strike, +6 parry. W.P. Short swords: +4 strike, +6 parry, +1 thrown.', '[{"name":"Recognize enchantment","pct":40}]', 'W.P. Knives, W.P. Large swords, W.P. Short swords.', NULL, 'All power words of alarm, blind, charm, confusion, dark, death, despair, energy, fear, mystic drain, sleep, undead, colors, numbers and permanence.', 'Minor psionic, I.S.P. 32: aura of truth, meditation, object read, presence sense, resist thirst, resist fatigue, sense magic.', NULL, NULL, 'Soft leather armour (A.R. 9, S.D.C. 20); magic dwarven broad sword (+2 strike/parry/dodge); 3 dwarven daggers; magic ring (metamorph twice daily); 4 doses of pixie dust; 14 doses of fire dust (causes -4 strike/parry/dodge); silk underdress; black hooded cloak; soft leather boots; dwarven war mask.', NULL, 'Manipulates Matlock for riches and influence, will deal with adventurers only at a steep price, and cares nothing for anyone''s life.', 'Spaz, her lover; King Matlock as her pawn', NULL, 'An elf who runs the armoury from behind the Mad Dwarf''s throne, always cloaked and masked so he never learns what she is. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.193'),
('spaz-place-of-magic', 'Spaz', 'Ralph Broff', 'Assassin of the Mad Dwarf''s court, the Armoury (Place of Magic)', 'palladium-fantasy', 'Human', '5th level Assassin', 5, 'Diabolic', NULL, '6 ft', NULL, '{"IQ":10,"PS":11,"PP":15,"PB":11,"Spd":11}', 51, NULL, NULL, NULL, NULL, 14, NULL, '{"attacks":3,"damage":2}', 'First-edition figures, as printed. Critical strike from behind. A.R. 14 is Dwarven Magic Chain Mail (silent, S.D.C. 80). W.P. Knives: +2 strike, +1 parry, +3 thrown. W.P. Large Sword: +2 strike, +2 parry, +1 thrown. W.P. Short Sword: +2 strike, +2 parry, +1 thrown. W.P. Blunt: +3 strike, +1 parry, +1 thrown. W.P. Short Bow: +2 strike, 4 attacks per melee. Can poison and fire 2 arrows per melee.', '[{"name":"Disguise","pct":48},{"name":"Prowl","pct":62},{"name":"Pick pockets","pct":40},{"name":"Use poison","pct":55},{"name":"Imitate voice","pct":58},{"name":"Ventriloquism","pct":48}]', 'Speaks elvish, eastern, western and goblin. W.P. Knives, Large Sword, Short Sword, Blunt, Short Bow.', NULL, 'Spells: None.', NULL, NULL, NULL, 'Dwarven Magic Chain Mail (silent, A.R. 14, S.D.C. 80); 4 daggers; broad sword; short sword; small hidden cudgel; short bow; 42 normal arrows; red sapphire magic ring (half damage from fire); leather and silver wrist band (strength of Utgard Loke, 3 times daily); 20 arrow doses of Basilisk''s Eye poison; 12 arrow doses of Scorpion Blood poison.', NULL, 'Sly and quick-witted, faithful to Sara alone, and reaches for poisoned arrows when things look dangerous.', 'Sara', NULL, 'A human assassin and Sara''s lover, one of the three who rule the Mad Dwarf''s armoury. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.193'),
('groggle-mean', 'Groggle-Mean', NULL, 'Goblin straggler, the Dwarven Complex (Place of Magic)', 'palladium-fantasy', 'Goblin', '3rd level Thief', 3, 'Miscreant', NULL, NULL, NULL, '{"IQ":7,"PP":13,"Spd":7}', 27, NULL, NULL, NULL, NULL, 13, NULL, '{"attacks":2,"parry":2,"dodge":2}', 'First-edition figures, as printed. A.R. 13 is chain (S.D.C. 44). W.P. knives +1 to strike/throw; ball and chain +2 strike; sling +1 to strike, 3 attacks per melee.', NULL, 'W.P. knives, ball and chain, sling.', NULL, NULL, NULL, NULL, NULL, 'Chain armour (A.R. 13, S.D.C. 44); 6 knives; ball and chain; sling.', '80 gold pieces and a ruby worth 270 gold.', NULL, 'Snide and Lop-Ear Grundle', NULL, 'One of three survivors of a larger goblin band, holed up in room M-8 and too frightened to go on or back. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.198'),
('snide-place-of-magic', 'Snide', NULL, 'Goblin straggler, the Dwarven Complex (Place of Magic)', 'palladium-fantasy', 'Goblin', '4th level Mercenary', 4, 'Anarchist', NULL, NULL, NULL, '{"IQ":7,"PP":18,"Spd":9}', 33, NULL, NULL, NULL, NULL, 15, NULL, '{"attacks":2,"strike":2,"parry":4,"dodge":4,"damage":2}', 'First-edition figures, as printed. A.R. 15 is dwarven scale armour (S.D.C. 75). W.P. large sword +2 to strike/parry; battle axe +2 strike/throw, +1 parry.', NULL, 'W.P. large sword, battle axe.', NULL, NULL, NULL, NULL, NULL, 'Dwarven scale armour (A.R. 15, S.D.C. 75); battle axe; broad sword.', '110 gold pieces, 40 silver and an emerald ring worth 350 gold.', NULL, 'Groggle-Mean and Lop-Ear Grundle', NULL, 'One of three survivors of a larger goblin band, holed up in room M-8 of the dwarven complex. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.198'),
('lop-ear-grundle', 'Lop-Ear Grundle', NULL, 'Hob-goblin straggler, the Dwarven Complex (Place of Magic)', 'palladium-fantasy', 'Hob-goblin', NULL, NULL, 'Anarchist', NULL, NULL, NULL, '{"IQ":3,"ME":16,"PS":10,"PE":14}', 39, NULL, NULL, NULL, NULL, 15, NULL, NULL, 'First-edition figures, as printed. +1 vs. psionics. A.R. 15 is chain mail (S.D.C. 44). W.P. knives +1 strike/throw; short sword +1 strike, +3 parry/dodge; short bow +3 strike, 4 attacks per melee. No class or level is printed.', '[{"name":"Identify tracks","pct":56}]', 'W.P. knives, short sword, short bow.', NULL, NULL, NULL, NULL, NULL, 'Chain mail (A.R. 15, S.D.C. 44); short sword; 3 daggers; short bow with 18 normal arrows and 4 magic lightning arrows; silver cross worn openly.', '70 gold pieces and 50 silver pieces.', 'Will not sign on to fight an Old One or hinder those who do, and might part with two magic arrows for another archer.', 'Groggle-Mean and Snide', NULL, 'A hob-goblin bowman travelling with two goblins; he keeps a private retreat in room M-10 of the dwarven complex. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.198'),
('artimus-gordon', 'Artimus Gordon', NULL, 'Wizard and zombie master of the Dwarven Complex (Place of Magic)', 'palladium-fantasy', 'Human', '15th level Wizard', 15, 'Unprincipled (once Scrupulous)', NULL, NULL, NULL, '{"IQ":14}', 84, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":2}', 'First-edition figures, as printed. Attacks per melee: 2 spells. +4 spell strength, +4 save against spells, +3 vs. circles/wards. Armour: None. W.P. Staves: +6 strike, +5 parry, +4 thrown. W.P. Knives: +5 strike, +5 parry, +8 thrown.', '[{"name":"Sense evil","pct":55},{"name":"Recognize enchantment","pct":80},{"name":"Recognize magic item","pct":60}]', 'W.P. Staves, W.P. Knives.', NULL, 'Casts 23 spells. Charm, create bread and milk, paralysis, sense evil, slumber, water to wine, invisibility (self), carpet of adhesion, mesmerism, tongues, globe of light, chameleon, sense traps, fleet feet, fly, reduce object, armour of ithan, call lightning, fireball, magic pigeon, magic net, diminish others, extinguish fire, turn dead, circle of rain, dispel magic barrier, see wards (7th level), create zombies (8th level).', NULL, NULL, NULL, 'Iron staff; 3 silver knives; magic ring (impervious to fire); bronze medallion (protection from witches); threadbare robe and sandals.', '50 gold pieces and 20 silver coins in the chest in his room, M-39.', 'Mournful and ashamed of serving the Old One out of terror; warns travellers off, fights only when defied, then strikes fast without cruelty and always accepts a surrender.', 'His legion of zombies', NULL, 'An aged, balding wizard bound unwillingly to the Old One, who screens the way to its complex from room M-39 with a host of zombies. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.198-199'),
('black-mist-place-of-magic', 'Black Mist', NULL, 'Possessing entity of room M-49, the Dwarven Complex (Place of Magic)', 'palladium-fantasy', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"IQ":7}', 70, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. I.Q. 7 is printed for it once it possesses someone. Standard save vs. magic against the possession.', NULL, NULL, 'As a mist it can do nothing except try to take over a body, one victim after another. Psionic attacks can destroy the mist, but once it has a host such an attack kills the host. In a body it gains bio-regeneration, knows what the victim knows, and is driven out by exorcism or the host''s death, after which it looks for another.', NULL, NULL, NULL, NULL, NULL, NULL, 'Devious and vicious.', NULL, NULL, 'A dark vapour sealed behind the door of room M-49 that pours out to seize whoever opens it; survivors of a possession must roll for insanity. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.199-201'),
('lord-gearm-drath', 'Lord Gearm-Drath', NULL, 'Dwarven mummy of the hidden corridor M-51, the Dwarven Complex (Place of Magic)', 'palladium-fantasy', 'Dwarf', '4th level Mind Mage (mummy)', 4, 'Unprincipled', NULL, '3 ft 4 in', NULL, '{"IQ":8,"ME":22,"Spd":7}', 53, NULL, NULL, NULL, 63, 12, NULL, '{"attacks":2,"damage":6}', 'First-edition figures, as printed. Attacks per melee: 2 normal and 2 psionic. +3 on all magical saves, +6 on psionic saves, +5 on saves against insanity. A.R. 12, affected by silver, magic and holy weapons only; his Armour of Dwarven Ken is A.R. 16, S.D.C. 235. W.P. Battle axe: +2 strike, +1 parry, +2 thrown. W.P. Throwing axe: +1 strike, +3 thrown.', '[{"name":"Prowl","pct":68}]', 'W.P. Battle axe, W.P. Throwing axe.', 'Sees in the dark to 90 ft and has claws.', NULL, '63 I.S.P., Master Psionic, knows all 1st through 4th level psionics (printed under Spells).', NULL, NULL, 'The axe of Dwarven Ken (magical artifact: +3 to strike, +3 to parry; edge glows red when elves or faerie folk are within 35 ft; handle glows green near poison gas or fumes; dark orange gem glows when touched to a magic item, ward, circle or rune); 2 throwing axes; the Armour of Dwarven Ken (full magical plate, A.R. 16, S.D.C. 235, weightless, impervious to fire); leather sack.', '7 complete Old Kingdom Dragon coins.', 'Weary beyond measure and asks only whether the hour has come; fights only if struck or if elves are there, and may tip a courteous visitor a coin.', NULL, 'Elves', 'A perfectly preserved dwarf lord lying in a warded, undiscovered corridor since dwarven times, his eyes reduced to points of cold blue light. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.201'),
('pyt-vyn', 'Pyt Vyn', NULL, 'The blind Basilisk of the Old One Complex (Place of Magic)', 'palladium-fantasy', 'Basilisk', '8th level Scholar', 8, 'Unprincipled', NULL, NULL, NULL, '{"IQ":14,"PS":22,"PP":13,"Spd":18}', 38, NULL, NULL, NULL, NULL, 10, NULL, '{"attacks":2,"damage":6}', 'First-edition figures, as printed. Attacks are 2 by claw. A.R. 10 is natural armour. Other attributes are average (not printed). Printed under the heading "The Basilisk (true name: Pyt Vyn)".', NULL, NULL, 'Having lost his eyes he is no longer able to turn anyone to stone.', NULL, NULL, NULL, NULL, NULL, NULL, 'Mild and frightened; begs not to be hurt, refuses to serve the Old One, and grows more forthcoming the more kindly he is treated, but will not travel with a party.', 'Anyone trying to stop the Old One', 'The Old One''s minions, who torment him', 'A scholar who came to the Place of Magic with Alsto Stone, was blinded after trying to foil the plot to wake the Old One, and now hides in the rubble of room M-63 knowing much about the witch, the minions and the Hall of Angels. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.203-205'),
('brutus-place-of-magic', 'Brutus', NULL, 'Assassin at guard post M-69, the Old One Complex (Place of Magic)', 'palladium-fantasy', NULL, '2nd level Assassin', 2, 'Diabolic', NULL, NULL, NULL, NULL, 18, NULL, NULL, NULL, NULL, 9, NULL, NULL, 'First-edition figures, as printed. Level is printed in words ("second level assassin"). A.R. 9 is soft leather armour (S.D.C. 20). 25% chance he is at the post.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Soft leather armour (A.R. 9, S.D.C. 20); sling; dagger; short sword.', NULL, NULL, NULL, NULL, 'A minion of the Old One who may be on duty at the small guard post M-69; his race is not printed. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.205'),
('the-witch-place-of-magic', 'The Witch', 'Sharon Cranton', 'Witch and leader of the Old One''s minions, the Old One Complex (Place of Magic)', 'palladium-fantasy', NULL, '6th level Witch', 6, 'Diabolic', NULL, NULL, NULL, '{"IQ":9,"PP":14,"PB":13,"Spd":11}', 46, NULL, NULL, NULL, NULL, NULL, NULL, '{"attacks":1}', 'First-edition figures, as printed. Hit Points are printed 46 (+20 from familiar). Attacks per melee: 1 hand to hand or 2 spells. +1 spell strength, +1 to save vs. all magic. Armour: None. Other attributes are average (not printed).', '[{"name":"Prowl","pct":53},{"name":"Use poison","pct":60},{"name":"Speaks southern and goblin","pct":100}]', NULL, 'Four times a day she can regenerate 2-12 hit points.', '8 spells daily: paralysis bolt, carpet of adhesion, wind rush, armour of ithan, diminish others, shadow walk, mystic portal and mute. Bound to the Old One for her power.', NULL, NULL, NULL, '3 daggers; emerald ring (worth 1200 gold). In her room M-72: 740 in gold coins, a potion of truth serum, a potion of shrinking, and a faintly glowing holy short sword (+6 damage, expels demons and devils).', '50 gold on her person.', 'Vicious and crafty, a zealot who longs to give her body to the Old One and would die for it; every minion but Grol-tee is afraid of her.', 'Her devil-kin familiar; Grol-tee; the Old One''s minions', NULL, 'The woman who leads the cult working to free the Old One, living in room M-72 beside the six circles; it plans to move its soul into her. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.207'),
('familiar-of-the-witch-place-of-magic', 'Familiar of the Witch', NULL, 'Devil-kin familiar of the Witch, the Old One Complex (Place of Magic)', 'palladium-fantasy', 'Devil-kin', NULL, NULL, 'Diabolic', NULL, NULL, NULL, NULL, 39, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'First-edition figures, as printed. +2 on all saving throws. The book refers to devil-kin in the Palladium R.P.G., pg. 184, for the rest.', NULL, NULL, 'Takes the shape of a big grey cat.', 'Can cast 8 spells daily; knows all fire elemental spells, level 1-3.', NULL, NULL, NULL, NULL, NULL, NULL, 'The Witch', NULL, 'The witch''s familiar, which has a 70% chance of being in her room M-72 and lends her 20 hit points. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.207'),
('grol-tee-the-protector', 'Grol-tee the Protector', NULL, 'Guardian of the Hall of Angels, the Old One Complex (Place of Magic)', 'palladium-fantasy', 'Minotaur', '4th level Mercenary Fighter', 4, 'Diabolic', NULL, NULL, NULL, '{"IQ":8,"PS":22,"PP":19,"PE":20}', 76, NULL, NULL, NULL, NULL, 13, NULL, '{"attacks":3,"strike":5,"parry":5,"dodge":5,"damage":9}', 'First-edition figures, as printed. Attacks per melee: 3 hand to hand or charge with horns. +3 to save vs. magic and poison (+1 from medallion). A.R. 13 is patch work plate and chain (S.D.C. 50). P.S. 22 is printed with "+7 to damage" while Bonuses prints +9 to damage. Other attributes are average (not printed). Class is spelled "Mercenery Fighter" in the book.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Patch work plate and chain (A.R. 13, S.D.C. 50); 2 daggers; giant size two handed axe; medallion of protection (+1 vs. magic); 2 small gems (worth 1000 gold).', '77 in gold coin.', 'A swaggering, vain bruiser who relishes tests of strength and fights dirty; he mistrusts spell casters and raises the alarm on seeing one.', 'The Witch and the Old One''s minions', NULL, 'The minotaur champion who watches the corridor to the golden doors from area M-80 or room M-82. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.207-208'),
('kimmbot', 'Kimmbot', 'Kalvin Klyn', 'Diabolist among the Old One''s minions, the Old One Complex (Place of Magic)', 'palladium-fantasy', NULL, '3rd level Diabolist', 3, 'Miscreant', NULL, NULL, NULL, '{"IQ":12}', 22, NULL, NULL, NULL, NULL, 12, NULL, '{"attacks":1}', 'First-edition figures, as printed. +2 save vs. wards, +1 save vs. circles. A.R. 12 is studded leather (S.D.C. 38). Other attributes are average (not printed).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Studded leather (A.R. 12, S.D.C. 38); dagger; short sword; a variety of tools, writing equipment, wax, silver leaf and a diary.', '120 gold.', 'A fussy, smartly turned-out man hungry for power and suspicious of everybody.', 'The Witch and the Old One''s minions', NULL, 'The cult''s diabolist. Room M-82 names a 3rd level diabolist "Mitchell Kindel" among the guards of the Hall of Angels, which is probably the same man under another name. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.208'),
('agu', 'Agu', NULL, 'One of the Old Ones (the Hierarchy of the Old Ones)', 'palladium-fantasy', 'Old One', NULL, NULL, 'Anarchist', NULL, NULL, NULL, NULL, 20000, NULL, NULL, NULL, 1000, 15, NULL, '{"attacks":4}', 'First-edition figures, as printed. Attacks per melee: 4 by spell or psionics. +5 to save vs. all magic, +4 spell strength. A.R. is natural. ALL Old Ones can read and use runes and rune magic and read and understand all symbols.', NULL, NULL, NULL, 'ALL wizard and elemental magic at 20th level proficiency. Clerical abilities: ALL at 20th level proficiency.', 'All, 1000 I.S.P.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Old One who stands for life, birth and rebirth, an oddity among its kind for delighting in those feelings. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.210'),
('al-vil', 'Al-vil', NULL, 'One of the Old Ones (the Hierarchy of the Old Ones)', 'palladium-fantasy', 'Old One', NULL, NULL, 'Diabolic', NULL, NULL, NULL, NULL, 10000, NULL, NULL, NULL, 500, 12, NULL, '{"attacks":2}', 'First-edition figures, as printed. Attacks per melee: 2 by psionics. +5 to save vs. all magic, +4 spell strength. A.R. is natural. ALL Old Ones can read and use runes and rune magic and read and understand all symbols.', NULL, NULL, NULL, 'ALL circle magic. Clerical abilities: None.', 'ALL, 500 I.S.P.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Old One who stands for envy and jealousy, a rotting horror; with Ya-blik it tricked Xy into the circle of transformation. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.210'),
('erva', 'Erva', NULL, 'One of the Old Ones (the Hierarchy of the Old Ones)', 'palladium-fantasy', 'Old One', NULL, NULL, 'Diabolic', NULL, NULL, NULL, NULL, 80000, NULL, NULL, NULL, 3000, 16, NULL, '{"attacks":4}', 'First-edition figures, as printed. Attacks per melee: 4 by psionics. +16 to save vs. all magic. A.R. is natural. ALL Old Ones can read and use runes and rune magic and read and understand all symbols.', NULL, NULL, NULL, 'Magic abilities: None. Clerical abilities: ALL at 15th level proficiency.', 'ALL, 3000 I.S.P.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Old One who stands for darkness and death: ignorance, dread of what is not understood, and the end of reason. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.210'),
('netosa', 'Netosa', NULL, 'One of the Old Ones (the Hierarchy of the Old Ones)', 'palladium-fantasy', 'Old One', NULL, NULL, 'Diabolic', NULL, NULL, NULL, NULL, 30000, NULL, NULL, NULL, 2000, 18, NULL, NULL, 'First-edition figures, as printed. Attacks per melee: via ward or circle. +8 to save vs. all magic. A.R. is natural. ALL Old Ones can read and use runes and rune magic and read and understand all symbols.', NULL, NULL, NULL, 'ALL circles and wards at 10th level proficiency. Clerical abilities: ALL at 10th level proficiency.', 'ALL levels 1-3, 2000 I.S.P.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Old One who stands for endless suffering, despair and the undead. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.210'),
('tarm-kin-toe', 'Tarm-kin-toe', NULL, 'One of the Old Ones (the Hierarchy of the Old Ones)', 'palladium-fantasy', 'Old One', NULL, NULL, 'Diabolic', NULL, NULL, NULL, NULL, 50000, NULL, NULL, NULL, 4000, 18, NULL, '{"attacks":5}', 'First-edition figures, as printed. Attacks per melee: 5 by spells or psionics. +10 to save vs. all magic. A.R. is natural. ALL Old Ones can read and use runes and rune magic and read and understand all symbols.', NULL, NULL, NULL, 'ALL spells, circles and wards at 10th level proficiency. Clerical abilities: ALL at 10th level proficiency.', 'ALL, 4000 I.S.P.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Old One who stands for hatred, treachery, vengeance and pain. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.210'),
('ya-ahk-met', 'Ya-ahk-met', NULL, 'One of the Old Ones (the Hierarchy of the Old Ones)', 'palladium-fantasy', 'Old One', NULL, NULL, 'Miscreant', NULL, NULL, NULL, NULL, 60000, NULL, NULL, NULL, 4000, 18, NULL, '{"attacks":4}', 'First-edition figures, as printed. Attacks per melee: 4 by spell or by psionics. +15 to save vs. all magic. A.R. is natural. ALL Old Ones can read and use runes and rune magic and read and understand all symbols.', NULL, NULL, NULL, 'ALL spell, elemental and circle magic at 20th level proficiency. Clerical abilities: ALL at 20th level proficiency.', 'ALL, 4000 I.S.P.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Old One who stands for power and light, the kind of might that sees nothing but its own aim and wrecks whatever is in the way. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.210'),
('ya-blik', 'Ya-blik', NULL, 'One of the Old Ones (the Hierarchy of the Old Ones)', 'palladium-fantasy', 'Old One', NULL, NULL, 'Diabolic', NULL, NULL, NULL, NULL, 80000, NULL, NULL, NULL, 3000, 18, NULL, '{"attacks":5}', 'First-edition figures, as printed. Attacks per melee: 5 by spell or psionic. +16 to save vs. all magic. A.R. is natural. ALL Old Ones can read and use runes and rune magic and read and understand all symbols.', NULL, NULL, NULL, 'ALL spells, elemental spells, circles and wards at 20th level proficiency. Clerical abilities: None.', 'ALL, 3000 I.S.P.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The Old One who stands for pestilence, betrayal and pain; with Al-vil it tricked Xy into the circle of transformation. A first-edition (1984) stat block.', 'The Palladium RPG Book II: Old Ones p.210');
